schemas.schema-04-reactions.prisma:
/// Discussion board post reactions - This model implements the requirement to enable users to express opinions (like/dislike) on posts, as documented in the business requirements (see Main Features: Voting, User Journeys: Member Participation). 
///
/// Business explanation: Records each user's reaction (like/dislike) to a specific post, enabling engagement tracking while preventing duplicate reactions per user per post. Maintains 3NF compliance by separating reaction data from post content and aggregations. For example, a user can 'like' a post, and this entry records their intent specifically for that post, without summary fields.
///
/// Key relationships: Links to the reacting member and the associated post. Special behaviors: Enforces one reaction per user per post through unique constraint, soft-deletes allow for undo/redo actions.
///
/// @namespace Reactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_reactions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each post reaction.
  id String @id @db.Uuid

  /// Belonged member's {@link discussionboard_members.id}. Indicates which registered member made the reaction.
  discussionboard_member_id String @db.Uuid

  /// Belonged post's {@link discussionboard_posts.id}. Associates the reaction with a particular post in the board.
  discussionboard_post_id String @db.Uuid

  /// Type of reaction - Implements the voting/feedback requirement.
  ///
  /// Business meaning: 'like', 'dislike', or future extension values (e.g. 'insightful'). Ensures normalization as all possible reactions are atomic per entry. For example, a member can express a 'like' or 'dislike' on a post, but never both simultaneously on the same post.
  ///
  /// Constraint: Application layer restricts values (enum); index allows future extensibility. Required field.
  reaction_type String

  /// Timestamp when the reaction was first recorded. Ensures accurate historical auditing to support undo functionality, behavioral patterns, or retroactive analysis. For example, seeing how engagement peaks over time.
  created_at DateTime @db.Timestamptz

  /// Soft-delete timestamp - Implements reversible actions.
  ///
  /// If null: Reaction is active; if set: reaction is considered deleted (e.g., user "unlikes" a post). Ensures normalization by not physically removing entries and maintaining an audit trail. Example: Allows for undo/redo of likes/dislikes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_postreaction_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_postreaction_post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, discussionboard_post_id])
  @@index([discussionboard_post_id])
  @@index([discussionboard_member_id])
  @@index([created_at])
}

/// Discussion board comment reactions - This model implements the requirement for users to provide feedback (likes/dislikes) on individual comments in discussion threads (see Main Features, User Journeys, and Engagement KPIs). 
///
/// Business explanation: Captures each user reaction to a comment, allowing fine-grained participation and sentiment analysis at the comment level. Maintains 3NF compliance by storing each user-comment reaction atomically. For example, a user can 'like' or 'dislike' a comment in a thread and this entry logs that action with traceability and reversibility.
///
/// Key relationships: Links to both the reacting member and the specific comment. Special behaviors: Enforces one reaction per user per comment, supports soft delete for undo/redo, and enables future extensibility for reaction types.
///
/// @namespace Reactions
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_comment_reactions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each comment reaction entry.
  id String @id @db.Uuid

  /// Belonged member's {@link discussionboard_members.id}. Identifies which platform member submitted the reaction to a comment.
  discussionboard_member_id String @db.Uuid

  /// Belonged comment's {@link discussionboard_comments.id}. Specifies the comment being reacted to.
  discussionboard_comment_id String @db.Uuid

  /// Type of reaction - Implements the core like/dislike feature for comments.
  ///
  /// Business meaning: Allowed values are 'like', 'dislike' (future-proof to support more). Atomic, normalized representation for each user-comment interaction. Ensures a member can record only a single reaction per comment. For example: registers a 'like' to a comment, excluding duplications.
  reaction_type String

  /// Timestamp at which the reaction was made. For accurate historical analysis, behavioral tracking, and compliance/auditing. Required field. For example, differentiates old vs new reactions.
  created_at DateTime @db.Timestamptz

  /// Soft-delete timestamp - Enables undo/redo for user feedback and preserves historical record, following audit trail requirements. Null means reaction is current; timestamp means it was removed/undone. Supports moderation and compliance.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_commentreaction_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  fk_commentreaction_comment discussionboard_comments @relation(fields: [discussionboard_comment_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, discussionboard_comment_id])
  @@index([discussionboard_comment_id])
  @@index([discussionboard_member_id])
  @@index([created_at])
}

schemas.schema-05-reports.prisma:
/// Report Entity - This implements the reporting and moderation requirements for tracking content suspected of violating platform rules (see sections 4, 5, and 6 in the requirements analysis). 
///
/// Business explanation: Each record represents a distinct instance where a member reports a post or comment for review, enabling formal moderation and resolution workflows. Maintains 3NF by storing each report and its relationships, without embedding calculated or summary data. For example, when a member flags a post for hate speech, a discussionboard_reports entry is created.
///
/// Key relationships: references the reported content (post or comment), the reporting member, and the selected category. Also links to the report's resolution log for auditability.
/// Special behaviors: Only authenticated members can submit; moderators/admins append resolution status through logs. Subsequent action is auditable through the associated logs.
///
/// @namespace Reports
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each report; satisfies normalization and distributed system compatibility.
  id String @id @db.Uuid

  /// Reporting member's {@link discussionboard_members.id}. Foreign key pointing to the user that submitted the report.
  reported_by_member_id String @db.Uuid

  /// Category's {@link discussionboard_report_categories.id}. Classifies the report according to the selected category (e.g., spam, harassment).
  report_category_id String @db.Uuid

  /// Target post's {@link discussionboard_posts.id}. Set when the report concerns a post. Nullable to support comment targeting.
  target_post_id String? @db.Uuid

  /// Target comment's {@link discussionboard_comments.id}. Set when the report concerns a comment. Nullable to support post targeting.
  target_comment_id String? @db.Uuid

  /// User-provided explanation for the report - Implements reporting detail requirements. Describes why the content was reported, supporting moderator decision-making. Example: 'This post contains personal attacks and inappropriate language.' Enforced as required for context clarity.
  description String

  /// Business status of the report, such as 'open', 'in_review', 'resolved', 'rejected' - Implements moderation workflow requirement. Used by moderators to track processing state. Only normalized status labels allowed here (no summary/calculation). Example: 'in_review'.
  status String

  /// Timestamp when report was created - Implements audit and traceability requirement. For example, helps measure report processing times.
  created_at DateTime @db.Timestamptz

  /// When the report was resolved - Implements resolution tracking requirement. Nullable for open/in-review reports. Example: when moderator completes review.
  resolved_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_reports_reported_by_member_id discussionboard_members @relation(fields: [reported_by_member_id], references: [id], onDelete: Cascade)
  fk_discussionboard_reports_report_category_id discussionboard_report_categories @relation(fields: [report_category_id], references: [id], onDelete: Cascade)
  fk_discussionboard_reports_target_post_id discussionboard_posts? @relation(fields: [target_post_id], references: [id], onDelete: Cascade)
  fk_discussionboard_reports_target_comment_id discussionboard_comments? @relation(fields: [target_comment_id], references: [id], onDelete: Cascade)

  discussionboard_report_logs discussionboard_report_logs[]

  @@index([reported_by_member_id])
  @@index([report_category_id])
  @@index([status])
  @@index([target_post_id])
  @@index([target_comment_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Report Log Entity - Implements audit and traceability requirements for the moderation process (requirements analysis section 3 and 5).
///
/// Business explanation: Records every status/action taken on a report (discussionboard_reports), providing a complete history for each case. Maintains 3NF by capturing atomic actions with actor, comment, and timestamp data; never stores pre-aggregated or summary fields. Used, for example, when a moderator changes a report's status or adds a resolution note.
///
/// Key relationships: Links to the underlying report and the acting moderator or admin. Enables full moderation workflow replay for compliance and accountability.
/// Special behaviors: Immutable (no edit/delete) after logging; supports audit trail for dispute handling.
///
/// @namespace Reports
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_report_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier per log entry, required for reliable chaining and auditability.
  id String @id @db.Uuid

  /// Reference to {@link discussionboard_reports.id}. Indicates which report this log entry documents.
  report_id String @db.Uuid

  /// Reference to {@link discussionboard_moderators.id}. Indicates which moderator or admin executed the log action.
  actor_moderator_id String @db.Uuid

  /// Moderation action performed - Implements step tracking requirement (e.g., 'assigned', 'in_review', 'replied', 'resolved', 'rejected', etc.). Maintains normalization by recording only atomic event. For example: 'resolved'.
  action String

  /// Optional comment by moderator/admin for context - Supports requirement for context-rich logs. May explain why action taken or rationale behind moderation. Example: 'User confirmed violation; post removed.' Nullable; not present for all actions.
  action_comment String?

  /// Time when log entry was created - Fulfills sequential/log order tracking requirement. Used for reconstructing timeline and compliance checking.
  timestamp DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_report_logs_report_id discussionboard_reports @relation(fields: [report_id], references: [id], onDelete: Cascade)
  fk_discussionboard_report_logs_actor_moderator_id discussionboard_moderators @relation(fields: [actor_moderator_id], references: [id], onDelete: Cascade)

  @@index([report_id])
  @@index([actor_moderator_id])
  @@index([timestamp])
  @@index([action_comment(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Report Category Entity - Implements the requirement to normalize types and reasons for reporting (requirements analysis section 4 and moderation flows).
///
/// Business explanation: Defines allowed, controlled vocabulary for report classification (e.g., 'spam', 'abuse', 'off-topic'). Ensures that all user reports have a meaningful, actionable category, which helps in triaging and statistical tracking. Maintains 3NF by representing each category as an atomic entity. For example, a user reporting spam selects the corresponding category_id.
///
/// Key relationships: Used as foreign key by discussionboard_reports for category normalization.
/// Special behaviors: Only Admin can add/edit/delete categories to prevent inconsistency.
///
/// @namespace Reports
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_report_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier per category to support reliable referencing.
  id String @id @db.Uuid

  /// Unique category name - Implements controlled vocabulary for valid report types. Example: 'spam'. Enforced unique for referential clarity.
  name String

  /// Category description - Explains category purpose to end-users/moderators. For example: 'Reports regarding unsolicited advertisements.' Required for clarity.
  description String

  //----
  // RELATIONS
  //----
  discussionboard_reports discussionboard_reports[]

  @@unique([name])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-06-moderation.prisma:
/// Moderation Action Log - This implements the 'Moderation Workflow' and 'Role-Specific Responsibilities' requirements, capturing every moderator/admin action taken on user-generated content. 
///
/// Business explanation: Stores a normalized, chronological log of all action events related to moderation (such as warning users, deleting posts, editing content, suspending accounts), ensuring accountability and traceability for dispute resolution and audits. Maintains 3NF by referencing related entities with foreign keys (not duplicating content or user-info). For example, useful for reconstructing a moderation timeline.
///
/// Key relationships: links to moderators/admins (actor), affected content (post/comment via foreign keys), and creates a record for appeals. Special behaviors: Immutable record—entries should never be deleted or altered after creation, only appended.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderation_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each moderation action log entry.
  id String @id @db.Uuid

  /// Moderator actor responsible for the moderation action - references the moderator who performed the action via {@link discussionboard_moderators.id} in Actors domain. Ensures role accountability. Nullable to allow actions performed by admins directly.
  moderator_id String? @db.Uuid

  /// Admin actor responsible for the moderation action - references the admin who performed the action via {@link discussionboard_admins.id} in Actors domain. Ensures role accountability. Nullable to allow actions performed by moderators directly.
  admin_id String? @db.Uuid

  /// Targeted post (if applicable) - references {@link discussionboard_posts.id} in Content domain. Nullable for actions not tied to a post (e.g., user warnings).
  target_post_id String? @db.Uuid

  /// Targeted comment (if applicable) - references {@link discussionboard_comments.id} in Content domain. Nullable for actions not tied to a comment.
  target_comment_id String? @db.Uuid

  /// Affected member - references {@link discussionboard_members.id}. The user who is the subject of the moderation action.
  affected_member_id String @db.Uuid

  /// Type of moderation action. Implements business logic around moderation event categorization (e.g., 'edit', 'delete', 'warn', 'suspend', 'reinstate'). Enables filtering and analytics. For example, supports reporting on frequency of warning vs deletion events.
  action_type String

  /// Explanation or reason for the moderation action. Implements requirement for documentation and transparency. Ensures normalization by separating event log from business rule/policy text. For example: 'Hate speech per Content Policy 2.3'.
  action_reason String

  /// Supplementary context or moderator note. Supports nuanced explanations for audits/disputes, and ensures normalization by storing annotations distinctly from main content. Example: 'Repeat offense after prior warning.'
  action_note String?

  /// Timestamp when the moderation action was recorded. Enables audit trails and time-based analyses. Enforces normalization by consistently storing event times in this domain table. Required and never null.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  moderation_action_moderator discussionboard_moderators? @relation(fields: [moderator_id], references: [id], onDelete: Cascade)
  moderation_action_admin discussionboard_admins? @relation(fields: [admin_id], references: [id], onDelete: Cascade)
  moderation_action_target_post discussionboard_posts? @relation(fields: [target_post_id], references: [id], onDelete: Cascade)
  moderation_action_target_comment discussionboard_comments? @relation(fields: [target_comment_id], references: [id], onDelete: Cascade)
  moderation_action_affected_member discussionboard_members @relation(fields: [affected_member_id], references: [id], onDelete: Cascade)

  discussionboard_moderation_appeals discussionboard_moderation_appeals[]

  @@unique([moderator_id, created_at])
  @@unique([admin_id, created_at])
  @@index([target_post_id, created_at])
  @@index([target_comment_id, created_at])
  @@index([affected_member_id, created_at])
  @@index([action_reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Moderation Appeals - Implements requirements from 'Escalation and Dispute Resolution' and 'Role-Specific Responsibilities', enabling members to appeal moderation outcomes. 
///
/// Business explanation: This table normalizes appeal submissions, allowing affected members to formally contest moderation actions. Maintains normalization by separating appeals from moderation logs and allowing multiple appeals per action if appropriate. For example, supports future analytics around appeal rates and outcomes.
///
/// Key relationships: links each appeal to a specific member (the appellant), the related moderation action, and creates the basis for related decisions. Special behaviors: Each appeal's status and progress is tracked, but business logic prevents duplicate active appeals for the same moderation action by the same member.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderation_appeals {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique ID for each moderation appeal.
  id String @id @db.Uuid

  /// The moderation action being appealed. References {@link discussionboard_moderation_actions.id}; implements requirement that appeals always correspond to a concrete moderation event.
  moderation_action_id String @db.Uuid

  /// Appellant member - references {@link discussionboard_members.id} (in Actors domain) of the user submitting the appeal.
  member_id String @db.Uuid

  /// Reason provided by the member for appeal. Ensures normalization by storing structured user input distinct from system logs. For example: 'Content removed in error, did not violate guideline.'
  appeal_reason String

  /// Current status of the appeal (e.g., 'pending', 'under_review', 'decided', 'withdrawn'). Supports business processes around escalation and supports queries on appeal state. Implemented as normalized string, not computed.
  appeal_status String

  /// Timestamp when the appeal was submitted. Required for time-based analytics and retention policies.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update to the appeal record (e.g., status change). Ensures proper lifecycle tracking.
  last_updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  appeal_moderation_action discussionboard_moderation_actions @relation(fields: [moderation_action_id], references: [id], onDelete: Cascade)
  appeal_member discussionboard_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  discussionboard_appeal_decisions discussionboard_appeal_decisions[]

  @@index([member_id])

  @@unique([moderation_action_id, member_id, appeal_status])
  @@index([created_at])
  @@index([appeal_reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Appeal Decisions - Implements the 'Appeals Process', 'Escalation and Dispute Resolution', and admin decision reporting requirements.
///
/// Business explanation: Captures individual decisions made during appeal review by moderators/admins. Normalizes how each decision on an appeal is recorded, who made it, and the rationale. Maintains normalization by separating decision data from appeals, supporting multi-stage review or panel votes. For example: can store decision history, rationales, and timestamps for compliance and analytics.
///
/// Key relationships: references specific appeals, identifies the admin/moderator who decided, and links to the Actors domain. Special behaviors: Once created, decisions are immutable, supporting audit trails.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_appeal_decisions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each appeal decision.
  id String @id @db.Uuid

  /// References the specific appeal under review, via {@link discussionboard_moderation_appeals.id}. Implements requirement that decisions are always tied to a submitted appeal.
  appeal_id String @db.Uuid

  /// Moderator making the appeal decision. References {@link discussionboard_moderators.id} for audit compliance. Nullable if the decision was made by an admin.
  moderator_id String? @db.Uuid

  /// Admin making the appeal decision. References {@link discussionboard_admins.id} for audit compliance. Nullable if the decision was made by a moderator.
  admin_id String? @db.Uuid

  /// Outcome of the appeal review (e.g., 'upheld', 'overturned', 'modified', 'escalated'). Implements normalized, auditable record of resolution.
  decision_outcome String

  /// Explanation of the decision (business/policy rationale). Ensures normalization by keeping detailed reasoning separate from logs. Example: 'Post restored; guideline not violated.'
  decision_rationale String

  /// Timestamp for when the decision was finalized. Required for audit trails and analytics.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  appeal_decision_appeal discussionboard_moderation_appeals @relation(fields: [appeal_id], references: [id], onDelete: Cascade)
  appeal_decision_moderator discussionboard_moderators? @relation(fields: [moderator_id], references: [id], onDelete: Cascade)
  appeal_decision_admin discussionboard_admins? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([moderator_id])
  @@index([admin_id])

  @@unique([appeal_id, moderator_id])
  @@unique([appeal_id, admin_id])
  @@unique([appeal_id, decision_outcome])
  @@index([created_at])
  @@index([decision_rationale(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-07-notifications.prisma:
/// Discussion Board Notification Entity - This model implements the delivery and audit requirement for all real-time and asynchronous notifications in the discussion board system, as specified in the requirements analysis for user feedback, moderation alerts, and system messages.
///
/// Business explanation: Each notification represents a single event delivered to a user (member, moderator, or admin) such as a mention, reply, moderation action, report escalation, or system notice. This design ensures proper 3NF compliance by storing atomic, individual notification records per user. For example, when a member is mentioned in a comment, a notification entry is created and delivered only to them.
///
/// Key relationships: Tied by foreign keys to members/actors table and content (post, comment, report, etc.). Allows targeting any user for any board event.
/// Special behaviors: Stores type, target, delivery/read status, and timestamps. Supports reliable delivery, tracking, and audit for compliance.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each notification record for audit and delivery tracking.
  id String @id @db.Uuid

  /// Target recipient's {@link discussionboard_members.id}. Links each notification to the intended user, who may be a member, moderator, or admin.
  recipient_member_id String @db.Uuid

  /// The user {@link discussionboard_members.id}, moderator, or admin who performed the action that generated this notification.
  trigger_actor_id String? @db.Uuid

  /// Type of notification (e.g., mention, reply, like, report, moderation_alert, system_announcement) - Implements requirement for tracking notification category and triggering appropriate UI rendering. Ensures normalization by storing type as an atomic string. Example: 'mention', 'report', 'system_announcement'.
  type String

  /// If this notification is about a post, the target post's {@link discussionboard_posts.id}. Null if N/A. Implements event referencing for modular notification design.
  target_post_id String? @db.Uuid

  /// If about a comment, the target comment's {@link discussionboard_comments.id}. Null if N/A.
  target_comment_id String? @db.Uuid

  /// If about a report, the relevant report's {@link discussionboard_reports.id}. Null if N/A.
  target_report_id String? @db.Uuid

  /// If about a section or board, references {@link discussionboard_sections.id}. Null if not applicable.
  target_section_id String? @db.Uuid

  /// Delivery timestamp for when notification was actually pushed to the user (email, web, etc.). Implements audit requirement for event delivery logs.
  delivered_at DateTime @db.Timestamptz

  /// Timestamp when the user viewed this notification. Null until read by recipient. Allows audit and unread count functionality.
  read_at DateTime? @db.Timestamptz

  /// Timestamp when the notification entry was created in the DB. Required for audit trail and sorting.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  recipient_member discussionboard_members @relation("discussionboard_notifications_of_recipient_member_id", fields: [recipient_member_id], references: [id], onDelete: Cascade)
  trigger_actor discussionboard_members? @relation("discussionboard_notifications_of_trigger_actor_id", fields: [trigger_actor_id], references: [id], onDelete: Cascade)

  @@index([recipient_member_id, created_at])
  @@index([trigger_actor_id, created_at])
  @@index([type, recipient_member_id, created_at])
}

/// Discussion Board Notification Preferences - Implements the user-configurable notification preference requirement for the discussion board system, allowing each member to choose which types or channels of notifications they wish to receive.
///
/// Business explanation: Each record links a member with their individual notification settings (e.g., email, push, web), supporting requirements for user personalization and compliance with communication opt-out regulations. Maintains proper 3NF by splitting member-to-preference mappings and avoids redundancy (no preferences stored on the member object itself).
///
/// Example: A user may silence 'system_announcement' notices but permit 'reply' and 'mention' notifications. Key relationships: belongs to one member, can be extended for per-channel preferences.
/// Special behaviors: Unique index per member, atomic on/off flags per notification type. Supports UI rendering for notification settings per member.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notification_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique per distinct preferences instance to support audit trails and changes.
  id String @id @db.Uuid

  /// Owner user's {@link discussionboard_members.id}. Each preferences record belongs to one member.
  member_id String @db.Uuid

  /// Whether to send notifications via email. Implements the multi-channel notification setting requirement (opt-in/out).
  enable_email Boolean

  /// Whether to send notifications via browser push. Example: Member disables all web push notifications but accepts email.
  enable_web_push Boolean

  /// If set, member will also get system-level announcements (policy changes, upgrades). Implements granular opt-in/out rule from requirements.
  enable_system_announcements Boolean

  /// Timestamp of preference entry creation. Enables audit and UI display of preference change recency.
  created_at DateTime @db.Timestamptz

  /// Last time any part of these preferences were changed. Allows compliance tracking per member.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member discussionboard_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@unique([member_id])
  @@index([enable_email])
  @@index([enable_web_push])
}

schemas.schema-08-policy.prisma:
/// Content Policy Model - This implements the 'policy definition & update tracking' requirement from the documented business rules and moderation policies. 
///
/// Business purpose: Governs community guidelines and permissible content on the board, defining what is and isn't allowed. Maintains 3NF by strictly separating policy meta from rule text, and associating with change logs for audit. For example, an admin can update this table to change offensive language filtering rules.
///
/// Key relationships: Referenced by logs, may be tied to moderation actions (defined in other domains).
/// Special behaviors: Effective/expiration tracking, scope of applicability, and active/withdrawn status.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_content_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each content policy.
  id String @id @db.Uuid

  /// Policy code - Implements the identification aspect of content policies for referencing in reports and logs. Business meaning: Unique short string (e.g., 'GENERAL', 'SPAM', 'HATE_SPEECH', etc.) that identifies this policy across the system. Ensures normalization by not reiterating policy meaning elsewhere; logs or moderation reference this code instead. For example, a moderator's action references 'SPAM' if acting under the anti-spam policy.
  code String

  /// Human-readable title of the policy - Implements requirement of clear policy communication. Business meaning: User-facing summary of the policy (e.g., 'No Hate Speech', 'No Spam'). Ensures normalization by preventing repetition in related tables. For example, visible to members on the board's policy page.
  title String

  /// Detailed policy text - Implements detailed requirement explanation from policy docs. Business meaning: The full text or markdown of the policy (rules, examples, etc). Ensures normalization by avoiding duplication in logs. For example, can be displayed as the guideline text in the board UI.
  description String

  /// Policy effective start timestamp - Implements versioning/audit need for knowing when this policy takes effect. Business meaning: From this datetime, the policy is in force. Ensures normalization by separating temporal aspects from identifiers/text. For example, new hate speech wording might be effective May 1, 2025.
  effective_from DateTime @db.Timestamptz

  /// Policy expiration/withdrawal timestamp - Implements requirement of temporal scoping. Business meaning: Until this datetime, the policy applies; null if still current. Ensures normalization—time scoping is managed in a single place. For example, an old policy that's replaced will have this set.
  effective_to DateTime? @db.Timestamptz

  /// Whether the policy is currently active - Implements enforcement logic. Business meaning: Admins can deactivate a policy for maintenance/retirement. Ensures normalization—removes special status flags from related tables. For example, inactive policies are hidden from UI and not enforced.
  is_active Boolean

  //----
  // RELATIONS
  //----
  discussionboard_policy_change_logs discussionboard_policy_change_logs[]

  @@unique([code])
  @@index([is_active])
  @@index([effective_from])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Business Rule Model - Implements the 'business rules, moderation logic, and platform-wide process configuration' requirements. 
///
/// Business purpose: Stores board-wide operational rules (such as edit/delete restrictions, notification toggles, content length maximums, etc). Maintains 3NF by storing only atomic rule properties, distinct from content policy details and change logs. For example, changing the maximum allowed post length updates this table.
///
/// Key relationships: May be referenced from moderation or configuration logs (other domains).
/// Special behaviors: Supports toggling, parameterizing, and enumerating global rule options (e.g., max edits, grace period mins).
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_business_rules {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each business rule.
  id String @id @db.Uuid

  /// Rule key - Implements structured reference and lookup for business rules system-wide. Business meaning: Unique identifier such as 'MAX_POST_LENGTH', 'ALLOW_POST_EDITING', etc. Ensures normalization by preventing duplication in logs or configs. For example: referenced programmatically or displayed in admin settings.
  key String

  /// Rule value - Implements requirement to parameterize settings. Business meaning: Value as string (can be int, bool, etc, encoded as string) for flexible config. Ensures normalization by centralizing config values. For example: '10000' for MAX_POST_LENGTH, 'true' for ALLOW_POST_EDITING.
  value String

  /// Rule human description - Implements requirement of explainability for business rules. Business meaning: User/admin-facing explanation of this rule and how it's applied. Ensures normalization by separating explanation from the rule key/value. For example: 'Maximum characters a post can have.'
  description String

  //----
  // RELATIONS
  //----
  discussionboard_policy_change_logs discussionboard_policy_change_logs[]

  @@unique([key])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Policy Change Log Model - Implements audit/compliance and traceability requirements from policy governance documentation. 
///
/// Business purpose: Records every change (add/modify/deactivate) to content policies or business rules, supporting rollback, accountability, and regulation compliance. Maintains 3NF by splitting log records from the entities being changed and snapshotting pre/post values. For example, when an admin updates a policy description, a record is inserted here.
///
/// Key relationships: Optionally references the changed policy or rule.
/// Special behaviors: Retains both the actor (admin) and before/after values for compliance audits.
///
/// @namespace Policy
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_policy_change_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each change log entry.
  id String @id @db.Uuid

  /// If non-null, links to the affected Content Policy's {@link discussionboard_content_policies.id}. For logging which policy was changed.
  changed_policy_id String? @db.Uuid

  /// If non-null, links to the affected Business Rule's {@link discussionboard_business_rules.id}. For logging which rule was changed.
  changed_rule_id String? @db.Uuid

  /// Admin actor performing the change - Links to the {@link discussionboard_admins.id} in Actors domain for compliance logging.
  actor_admin_id String @db.Uuid

  /// Type of change - Implements requirement to distinguish operations ('add', 'edit', 'deactivate', etc). Business meaning: Describes the action (enum-like); e.g., 'ADD', 'EDIT', 'DEACTIVATE'. Ensures normalization as a single column, referenced in reports, etc. For example: shown in the admin change history UI.
  change_type String

  /// Pre-change JSON value - Implements audit requirement of historical state. Business meaning: JSON-encoded string of content policy or rule before the change. Ensures normalization by snapshotting original value rather than duplicating all properties. For example, for edits, this holds the old version of the policy/rule.
  before_value String?

  /// Post-change JSON value - Implements audit requirement for traceability. Business meaning: JSON-encoded string of policy/rule after the change. Ensures normalization via atomic recording. For example: allows rollback if needed; basis for audit comparison.
  after_value String?

  /// Timestamp of change - Implements chronology/auditing requirement. Business meaning: When the change was made. Ensures strict temporal audit log. For example, supports timelines of admin actions.
  changed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  changed_policy discussionboard_content_policies? @relation(fields: [changed_policy_id], references: [id], onDelete: Cascade)
  changed_rule discussionboard_business_rules? @relation(fields: [changed_rule_id], references: [id], onDelete: Cascade)
  actor_admin discussionboard_admins @relation(fields: [actor_admin_id], references: [id], onDelete: Cascade)

  @@index([actor_admin_id, changed_at])
  @@index([changed_policy_id, changed_at])
  @@index([changed_rule_id, changed_at])
}

schemas.main.prisma:
