import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";
import type { IPageIDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardNotificationSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates paginated, filtered listing of discussion board notification settings as administrator (plus negative and edge cases).
 *
 * Ensures the following business rules:
 *  1. Only admins can list all (including potentially sensitive) notification settings.
 *  2. Supports filters by key, value, description, and creation timestamp.
 *  3. Pagination works: page and limit affect results and metadata as documented.
 *  4. Robust to edge cases: empty result set, page overflow, malformed pagination input.
 *  5. Unauthorized access is blocked.
 *
 * Steps:
 * 1. Create notification settings (with randomized keys/values/descriptions) as admin.
 * 2. Admin fetches with page/limit, validates response metadata and page contents.
 * 3. Admin filters by key, value, description, and date range; confirms filtering correctness.
 * 4. Admin attempts a filter that yields zero results, checks response.
 * 5. Admin requests an out-of-range page, verifies response is empty dataset, correct metadata.
 * 6. Negative: send PATCH with invalid page (0), expect error.
 * 7. Negative: unauthorized connection, expect error.
 */
export async function test_api_discussionBoard_notificationSettings_test_list_notification_settings_with_pagination_and_filters_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create test notification settings as admin
  const createdSettings: IDiscussionBoardNotificationSetting[] = [];
  for (let i = 0; i < 5; ++i) {
    const setting = await api.functional.discussionBoard.notificationSettings.post(connection, {
      body: {
        key: `key_${RandomGenerator.alphaNumeric(10)}`,
        value: `val_${RandomGenerator.alphaNumeric(8)}`,
        description: `desc ${RandomGenerator.alphabets(12)} for test ${i}`,
      } satisfies IDiscussionBoardNotificationSetting.ICreate,
    });
    typia.assert(setting);
    createdSettings.push(setting);
  }

  // Step 2: Admin fetches settings, page/limit (page=1, limit=3)
  const paginated = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      page: 1,
      limit: 3,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(paginated);
  TestValidator.equals("records >= created")(paginated.pagination.records >= 5)(true);
  TestValidator.equals("page 1 limit respected")(paginated.data.length)(3);
  TestValidator.equals("page index")(paginated.pagination.current)(1);
  TestValidator.equals("page count formula")(paginated.pagination.pages)(Math.ceil(paginated.pagination.records / paginated.pagination.limit));

  // Step 3a: Filter by key
  const filterKey = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      key: createdSettings[2].key,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterKey);
  TestValidator.equals("key filter result 1")(filterKey.data.length)(1);
  TestValidator.equals("filtered key matches")(filterKey.data[0].key)(createdSettings[2].key);

  // Step 3b: Filter by value
  const filterValue = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      value: createdSettings[4].value,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterValue);
  TestValidator.equals("value filter result 1")(filterValue.data.length)(1);
  TestValidator.equals("filtered value matches")(filterValue.data[0].value)(createdSettings[4].value);

  // Step 3c: Filter by description substring
  const descTerm = createdSettings[1].description?.slice(0, 6) ?? "desc";
  const filterDesc = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      description: descTerm,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterDesc);
  TestValidator.predicate("description filter includes at least one")(filterDesc.data.some(d => d.description?.includes(descTerm)));

  // Step 3d: Filter by created_at_from/created_at_to
  const { created_at } = createdSettings[0];
  const filterCreated = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      created_at_from: created_at,
      created_at_to: created_at,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(filterCreated);
  TestValidator.predicate("created_at filter >= 1")(filterCreated.data.length >= 1);
  TestValidator.equals("created_at match")(filterCreated.data[0].created_at)(created_at);

  // Step 4: Filter with no results (invalid key)
  const empty = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      key: "no_such_key_" + RandomGenerator.alphaNumeric(10),
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(empty);
  TestValidator.equals("empty filter result")(empty.data.length)(0);

  // Step 5: Fetch page out of bounds (page very high)
  const outOfRange = await api.functional.discussionBoard.notificationSettings.patch(connection, {
    body: {
      page: 99,
      limit: 10,
    } satisfies IDiscussionBoardNotificationSetting.IRequest,
  });
  typia.assert(outOfRange);
  TestValidator.equals("out of bounds is empty")(outOfRange.data.length)(0);

  // Step 6: Negative - invalid pagination (page 0)
  await TestValidator.error("page min constraint")(async () => {
    await api.functional.discussionBoard.notificationSettings.patch(connection, {
      body: {
        page: 0,
      } satisfies IDiscussionBoardNotificationSetting.IRequest,
    });
  });

  // Step 7: Negative - unauthorized (simulate missing admin)
  const headersNoAuth = { ...connection.headers };
  delete headersNoAuth.Authorization;
  const noAuthConnection: api.IConnection = { ...connection, headers: headersNoAuth };
  await TestValidator.error("unauthorized user")(async () => {
    await api.functional.discussionBoard.notificationSettings.patch(noAuthConnection, {
      body: {},
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * 관리자 권한으로 알림 설정 상세 조회 API를 테스트한다.
 *
 * 성공 케이스:
 *   - 이미 생성된 알림 설정 ID를 이용해 상세 조회 시, 모든 주요 필드(key, value, description, 생성/수정일 등)가 정확하게 반환되는지 확인
 *
 * 실패(비정상) 케이스:
 *   - 존재하지 않는 ID로 조회 시 404 not found 오류가 발생하는지 확인
 *   - (선택) 관리자가 아닌 일반 권한 또는 비로그인으로 접근할 경우 권한 오류가 발생하는지 확인 (connection 전환/권한 분리 환경 제공 가능 시에만)
 *
 * 테스트 단계
 * 1. 사전: 알림 설정 데이터를 생성한다(POST /discussionBoard/notificationSettings)
 * 2. 성공: 방금 생성한 알림 설정 ID로 상세 조회. 반환 필드와 값 일치 여부 비교
 * 3. 실패a: 존재하지 않는 무작위 uuid로 조회 시도 후 404 발생 확인
 * 4. 실패b: (선택) 비관리자/일반 사용자 connection에서 접근 시 권한 거부 오류 발생 확인 (시스템이 이를 지원할 경우만)
 */
export async function test_api_discussionBoard_notificationSettings_getById(
  connection: api.IConnection,
) {
  // 1. 알림 설정 데이터 생성(사전 준비)
  const createBody = {
    key: `unit_test_key_${RandomGenerator.alphaNumeric(8)}`,
    value: "immediate",
    description: "테스트용 알림 설정 설명입니다.",
  } satisfies IDiscussionBoardNotificationSetting.ICreate;
  const created = await api.functional.discussionBoard.notificationSettings.post(connection, { body: createBody });
  typia.assert(created);

  // 2. 성공 - 생성된 ID로 상세 조회 및 값 비교
  const fetched = await api.functional.discussionBoard.notificationSettings.getById(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals("id 일치")(fetched.id)(created.id);
  TestValidator.equals("key 일치")(fetched.key)(createBody.key);
  TestValidator.equals("value 일치")(fetched.value)(createBody.value);
  TestValidator.equals("description 일치")(fetched.description)(createBody.description ?? null);
  // created_at, updated_at 등은 서버에서 자동 생성이므로 단순 존재(assert)만 수행
  TestValidator.predicate("created_at valid")(!!fetched.created_at);
  TestValidator.predicate("updated_at valid")(!!fetched.updated_at);

  // 3. 실패a - 존재하지 않는 uuid로 조회 시도 시 404
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("존재하지 않는 ID는 404")(async () => {
    await api.functional.discussionBoard.notificationSettings.getById(connection, { id: nonExistentId });
  });

  // 4. 실패b - 비관리자 connection 권한(옵션, 시스템 지원 시)
  // 예시)
  // const userConnection = ... // 일반 사용자 권한 값 세팅(로그인 등)
  // TestValidator.error("비관리자 접근 시 권한 거부")(
  //   async () => {
  //     await api.functional.discussionBoard.notificationSettings.getById(userConnection, { id: created.id });
  //   },
  // );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * Tests admin creation of discussion board notification settings.
 *
 * This test covers comprehensive business logic and input validation:
 *   1. Create a new notification setting with a unique key and optional description (success case)
 *   2. Validate that the created record returns correct metadata (id, created_at, updated_at, etc), required fields, and optional fields
 *   3. Attempt to create another notification setting with the same key (should fail with duplicate key error)
 *   4. Attempt to create a setting omitting required fields (should fail validation)
 */
export async function test_api_discussionBoard_test_create_notification_setting_with_unique_key_and_duplicate_key_error(
  connection: api.IConnection,
) {
  // 1. Create setting with a unique key, value, and description (expect success)
  const uniqueKey = `notif_${RandomGenerator.alphabets(8)}`;
  const value = "immediate";
  const description = RandomGenerator.paragraph()();
  const createInput = {
    key: uniqueKey,
    value,
    description,
  } satisfies IDiscussionBoardNotificationSetting.ICreate;

  const created = await api.functional.discussionBoard.notificationSettings.post(connection, { body: createInput });
  typia.assert(created);

  // Field-level checks for created record
  TestValidator.equals("key matches input")(created.key)(uniqueKey);
  TestValidator.equals("value matches input")(created.value)(value);
  TestValidator.equals("description matches input")(created.description)(description);
  TestValidator.predicate("id is uuid")(
    typeof created.id === "string" && created.id.length > 0
  );
  TestValidator.predicate("created_at is date-time")(
    !!Date.parse(created.created_at)
  );
  TestValidator.predicate("updated_at is date-time")(
    !!Date.parse(created.updated_at)
  );
  TestValidator.equals("deleted_at should be null when just created")(created.deleted_at)(null);

  // 2. Duplicate key creates error
  await TestValidator.error("duplicate notification key errors out")(
    () =>
      api.functional.discussionBoard.notificationSettings.post(connection, {
        body: {
          key: uniqueKey,
          value: "daily",
          description: "Duplicate should fail",
        } satisfies IDiscussionBoardNotificationSetting.ICreate,
      })
  );

  // 3. Missing required 'key' field (should throw validation error)
  await TestValidator.error("missing key field works")(
    () =>
      api.functional.discussionBoard.notificationSettings.post(connection, {
        body: {
          // key omitted intentionally
          value: "immediate",
        } as any, // purposely invalid input for runtime validator
      })
  );

  // 4. Missing required 'value' field (should throw validation error)
  await TestValidator.error("missing value field triggers validation error")(
    () =>
      api.functional.discussionBoard.notificationSettings.post(connection, {
        body: {
          key: `k_${RandomGenerator.alphabets(6)}`,
          // value omitted intentionally
        } as any,
      })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * E2E test for updating a notification setting entry by ID as an admin.
 *
 * Business Context:
 * - This test ensures that administrators can successfully update notification setting entries, while non-admins are properly forbidden.
 * - Only the 'value' and 'description' fields of a notification setting may be updated. The 'key' is immutable after creation.
 *
 * Test Workflow:
 * 1. Create two notification settings as admin to prepare for unique key and data constraints.
 * 2. Update the value and description of the first notification setting; ensure change is reflected in response.
 * 3. Attempt to update the first setting with missing required field (no value) and expect a validation error.
 * 4. Attempt to update with malformed value type (number instead of string) and expect a validation error.
 * 5. Update the entry with description set to null (edge case for optional fields).
 * 6. Attempt update as unauthenticated or non-admin user; expect forbidden error.
 *
 * Note:
 * - The API schema does not allow changing the key of an existing entry via the update endpoint; thus, duplicate key testing on update is not possible here.
 */
export async function test_api_discussionBoard_notificationSettings_test_update_notification_setting_with_valid_data_and_duplicate_key_error(
  connection: api.IConnection
) {
  // 1. Create two distinct notification settings as admin
  const createInput1: IDiscussionBoardNotificationSetting.ICreate = {
    key: RandomGenerator.alphabets(10),
    value: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const setting1 = await api.functional.discussionBoard.notificationSettings.post(
    connection,
    { body: createInput1 }
  );
  typia.assert(setting1);

  const createInput2: IDiscussionBoardNotificationSetting.ICreate = {
    key: RandomGenerator.alphabets(10),
    value: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const setting2 = await api.functional.discussionBoard.notificationSettings.post(
    connection,
    { body: createInput2 }
  );
  typia.assert(setting2);

  // 2. Update first setting's value and description
  const updateInput: IDiscussionBoardNotificationSetting.IUpdate = {
    value: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
  };
  const updated = await api.functional.discussionBoard.notificationSettings.putById(
    connection,
    { id: setting1.id, body: updateInput }
  );
  typia.assert(updated);
  TestValidator.equals("updated value")(updated.value)(updateInput.value);
  TestValidator.equals("updated description")(updated.description)(updateInput.description);
  TestValidator.equals("updated id matches")(updated.id)(setting1.id);

  // 3. Edge case: Update with description set to null
  const updateNullDesc: IDiscussionBoardNotificationSetting.IUpdate = {
    value: RandomGenerator.alphabets(12),
    description: null,
  };
  const updatedNullDesc = await api.functional.discussionBoard.notificationSettings.putById(
    connection,
    { id: setting1.id, body: updateNullDesc }
  );
  typia.assert(updatedNullDesc);
  TestValidator.equals("updated value with null desc")(updatedNullDesc.value)(updateNullDesc.value);
  TestValidator.equals("updated description null")(updatedNullDesc.description)(null);

  // 4. Validation: Missing required 'value' property
  await TestValidator.error("missing value fails")(
    async () => {
      // Omit required 'value' by creating minimal malformed object
      await api.functional.discussionBoard.notificationSettings.putById(
        connection,
        { id: setting1.id, body: { /* intentionally empty */ } as unknown as IDiscussionBoardNotificationSetting.IUpdate },
      );
    }
  );

  // 5. Validation: Malformed 'value' property (number instead of string)
  await TestValidator.error("malformed value fails")(
    async () => {
      // Use object with 'value' as number, cast via JSON.parse
      const malformedBody = JSON.parse('{"value":123456, "description": "desc"}');
      await api.functional.discussionBoard.notificationSettings.putById(
        connection,
        { id: setting1.id, body: malformedBody },
      );
    }
  );

  // 6. Simulate non-admin or unauthenticated attempt: Remove likely auth headers
  const connectionNoAuth = {
    ...connection,
    headers: { ...(connection.headers ?? {}) }
  };
  delete connectionNoAuth.headers.Authorization;
  delete connectionNoAuth.headers.authorization;
  await TestValidator.error("forbidden for non-admin")(
    async () => {
      await api.functional.discussionBoard.notificationSettings.putById(
        connectionNoAuth,
        { id: setting1.id, body: updateInput },
      );
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardNotificationSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotificationSetting";

/**
 * Validate soft-deletion (logical deletion) of a discussion board notification setting.
 *
 * This test covers the following business and access control requirements:
 *
 * 1. Create a notification setting as an admin user (dependency).
 * 2. As admin, soft-delete the notification setting by its ID (verify `deleted_at` property is set, no physical removal).
 * 3. Attempt a redundant soft-delete by ID (expect an error as the entry is already deleted).
 * 4. Attempt to soft-delete a non-existent notification setting ID (expect an error response).
 * 5. Simulate non-admin (unauthorized) and verify deletion is forbidden (expect error).
 *
 * The test ensures core CRUD soft-delete logic for notification settings and validates access rules for the endpoint.
 */
export async function test_api_discussionBoard_notificationSettings_test_soft_delete_notification_setting_and_access_post_delete(
  connection: api.IConnection,
) {
  // 1. Create notification setting as admin
  const createInput: IDiscussionBoardNotificationSetting.ICreate = {
    key: RandomGenerator.alphabets(10),
    value: RandomGenerator.alphabets(8),
    description: RandomGenerator.paragraph()(),
  };
  const setting = await api.functional.discussionBoard.notificationSettings.post(connection, { body: createInput });
  typia.assert(setting);

  // 2. Admin soft-deletes the notification setting
  const erased = await api.functional.discussionBoard.notificationSettings.eraseById(connection, { id: setting.id });
  typia.assert(erased);
  TestValidator.equals("deleted_at must be set after deletion")(typeof erased.deleted_at === "string")(true);
  TestValidator.equals("ID is preserved after logical deletion")(erased.id)(setting.id);
  TestValidator.equals("key is preserved after logical deletion")(erased.key)(setting.key);
  TestValidator.equals("value is preserved after logical deletion")(erased.value)(setting.value);

  // 3. Attempt to soft-delete already deleted ID (should throw)
  await TestValidator.error("cannot erase an already deleted setting")(() =>
    api.functional.discussionBoard.notificationSettings.eraseById(connection, { id: setting.id })
  );

  // 4. Attempt to soft-delete a non-existent ID (should throw)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("cannot erase a non-existent setting")(() =>
    api.functional.discussionBoard.notificationSettings.eraseById(connection, { id: fakeId })
  );

  // 5. Try to soft-delete as unauthorized/non-admin (simulate by deleting Authorization header)
  const { Authorization, ...restHeaders } = connection.headers ?? {};
  const unauthorized: api.IConnection = {
    ...connection,
    headers: restHeaders,
  };
  await TestValidator.error("forbidden for non-admin/unauthorized")(() =>
    api.functional.discussionBoard.notificationSettings.eraseById(unauthorized, { id: setting.id })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * 관리자 권한으로 토론 게시판 회원 목록을 페이지네이션과 검색 조합으로 조회, 검증한다.
 *
 * - 여러 명의 회원 가입(서로 구분 가능한 username/email 패턴 적용)
 * - 특정 계정 admin 등업 처리 (최초 user → admin 전환 논리)
 * - 다양한 페이지, 검색 조합으로 목록 API 호출 및 검증
 *     - username, email 전체/부분/불일치 검색
 *     - page/limit 정상 및 비정상(0, 음수) 케이스
 *     - 결과 전체건수/페이지/limit 등 pagination 정보의 정합성
 *     - 검색조건 불충족(empty result) 확인
 */
export async function test_api_discussionBoard_test_list_members_with_pagination_and_search_by_admin(
  connection: api.IConnection,
) {
  // 1. 테스트용 회원 데이터 여러 개 생성 (username/email 구분되게)
  const members: IDiscussionBoardMember[] = [];
  for (let i = 0; i < 7; ++i) {
    const suffix = String(i + 1).padStart(2, "0");
    const username = `autotest_member_${suffix}`;
    const email = `autotest_member_${suffix}@testdomain.dev` as string & tags.Format<"email">;
    const member = await api.functional.discussionBoard.members.post(connection, {
      body: {
        username,
        email,
        display_name: `테스트유저${suffix}`,
        password: "Password123!" as string & tags.Format<"password">,
      },
    });
    typia.assert(member);
    members.push(member);
  }

  // 2. 관리자용 계정 생성 및 admin 등업(권한에 필요한 appointing admin 지정)
  const adminUsername = "autotest_admin";
  const adminEmail = "autotest_admin@testdomain.dev" as string & tags.Format<"email">;
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      display_name: "관리자유저",
      password: "SecureAdminPW!1" as string & tags.Format<"password">,
    },
  });
  typia.assert(adminMember);

  // manager self-appoints/assigns as admin (최초 admin이면 자기 자신 지정, 아니면 기존 admin이 지정 필요)
  const adminAssignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: adminMember.id,
      appointed_by_admin_id: adminMember.id,
    },
  });
  typia.assert(adminAssignment);

  // 3. 페이징+검색 조합으로 목록 조회

  // (a) 전체회원 page=1, limit=3
  let result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 3 },
  });
  typia.assert(result);
  TestValidator.equals("페이지 개수 = limit")(result.data.length)(3);
  TestValidator.equals("pagination.current")(result.pagination.current)(1);
  TestValidator.equals("pagination.limit")(result.pagination.limit)(3);
  // 총 회원 수가 (members + 관리자 1명)
  TestValidator.equals("pagination.records, 총 회원 수")(
    result.pagination.records,
  )(members.length + 1);

  // (b) username 부분일치(autotest_member_0) 검색 (page=1, limit=10)
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, username: "autotest_member_0" },
  });
  typia.assert(result);
  // username에 "autotest_member_0" 포함된 회원만 반환
  for (const u of result.data) {
    TestValidator.predicate("username 부분일치 검색 결과 필터")(
      u.username.includes("autotest_member_0"),
    );
  }

  // (c) email 전체일치 검색
  const targetEmail = members[3].email;
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, email: targetEmail },
  });
  typia.assert(result);
  TestValidator.equals("email 전체일치 사용자 단 1인 반환됨")(
    result.data.length,
  )(1);
  TestValidator.equals("반환 email값 매칭")(
    result.data[0].email,
  )(targetEmail);

  // (d) 존재하지 않는 display_name 검색(빈 결과)
  result = await api.functional.discussionBoard.members.patch(connection, {
    body: { page: 1, limit: 10, display_name: "__존재하지않음__" },
  });
  typia.assert(result);
  TestValidator.equals("display_name 불일치 검색 결과, 비어있음")(
    result.data.length,
  )(0);

  // (e) invalid page, limit(0/음수 등) → 에러 확인
  for (const params of [ { page: 0, limit: 3 }, { page: -1, limit: 2 }, { page: 2, limit: 0 } ]) {
    await TestValidator.error(`잘못된 page/limit: ${JSON.stringify(params)}`)(
      async () => {
        await api.functional.discussionBoard.members.patch(connection, {
          body: params,
        });
      },
    );
  }
}

