import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Validate that an administrator can update another discussion board member's profile (display name, email, password) under all business constraints.
 *
 * Business context: On a discussion board platform, only admins are allowed to update other users' profiles. Each member must have a unique email. Usernames are immutable. Tests must cover uniqueness violations, forbidden update attempts, and not-found errors for robustness.
 *
 * Steps:
 * 1. Register an initial member (requester).
 * 2. Promote the requester to admin by creating an admin assignment (self-promotion for the seed admin).
 * 3. Register a target member whose profile will be updated.
 * 4. As admin, update the target member's display name and email to new, valid values; expect the response to reflect changes.
 * 5. Validate the changes (via returned output).
 * 6. Try updating to an already-used email (from another member); expect uniqueness error (TestValidator.error).
 * 7. As a non-admin (original target user), attempt to update another member; expect forbidden error (TestValidator.error).
 * 8. Attempt to update a non-existent member; expect not found error (TestValidator.error).
 */
export async function test_api_discussionBoard_test_update_member_profile_by_admin_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register the requester (who will be admin)
  const adminEmail = typia.random<string & tags.Format<'email'>>();
  const adminUsername = RandomGenerator.alphaNumeric(12);
  const adminDisplayName = RandomGenerator.name();
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const requester = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: adminUsername,
      email: adminEmail,
      display_name: adminDisplayName,
      password: adminPassword,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(requester);
  TestValidator.equals("admin registration email")(requester.email)(adminEmail);
  TestValidator.equals("admin registration username")(requester.username)(adminUsername);
  TestValidator.equals("admin registration display_name")(requester.display_name)(adminDisplayName);

  // 2. Promote to admin (self-appointment for test: appoint self as admin because no prior admin)
  const adminRecord = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: requester.id,
      appointed_by_admin_id: requester.id,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminRecord);
  TestValidator.equals("admin record appointed member")(adminRecord.member_id)(requester.id);
  TestValidator.equals("admin record appointor")(adminRecord.appointed_by_admin_id)(requester.id);

  // 3. Register a target member
  const targetEmail = typia.random<string & tags.Format<'email'>>();
  const targetUsername = RandomGenerator.alphaNumeric(12);
  const targetDisplayName = RandomGenerator.name();
  const targetPassword = RandomGenerator.alphaNumeric(16);
  const target = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: targetUsername,
      email: targetEmail,
      display_name: targetDisplayName,
      password: targetPassword,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(target);
  TestValidator.equals("target registration username")(target.username)(targetUsername);
  TestValidator.equals("target registration email")(target.email)(targetEmail);
  TestValidator.equals("target registration display_name")(target.display_name)(targetDisplayName);

  // 4. As admin, update the target member's display_name & email
  const newEmail = typia.random<string & tags.Format<'email'>>();
  const newDisplayName = RandomGenerator.name();
  const updateResult = await api.functional.discussionBoard.members.putById(connection, {
    id: target.id,
    body: {
      email: newEmail,
      display_name: newDisplayName,
      password: targetPassword + "_CHANGED", // updating password too
    } satisfies IDiscussionBoardMember.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("updated email")(updateResult.email)(newEmail);
  TestValidator.equals("updated display_name")(updateResult.display_name)(newDisplayName);
  TestValidator.equals("username not changed")(updateResult.username)(targetUsername);

  // 5. Validate the changes via returned output (done above)

  // 6. Try updating with an already-used email (uniqueness violation: using admin's email)
  await TestValidator.error("duplicate email is not allowed")(() =>
    api.functional.discussionBoard.members.putById(connection, {
      id: target.id,
      body: {
        email: adminEmail, // already used by requester/admin
        display_name: RandomGenerator.name(),
        password: targetPassword + "_NEW_2",
      } satisfies IDiscussionBoardMember.IUpdate,
    })
  );

  // 7. As non-admin, try forbidden update: target user attempts to modify requester (should fail)
  await TestValidator.error("non-admin cannot update another user's profile")(() =>
    api.functional.discussionBoard.members.putById(connection, {
      id: requester.id, // target member tries to update admin
      body: {
        email: typia.random<string & tags.Format<'email'>>(),
        display_name: "bad update attempt",
      } satisfies IDiscussionBoardMember.IUpdate,
    })
  );

  // 8. Attempt to update a non-existent member
  await TestValidator.error("updating nonexistent member should throw")(() =>
    api.functional.discussionBoard.members.putById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: {
        email: typia.random<string & tags.Format<'email'>>(),
        display_name: RandomGenerator.name(),
        password: RandomGenerator.alphaNumeric(12),
      } satisfies IDiscussionBoardMember.IUpdate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";

/**
 * Test deleting a discussion board member as an admin, and edge cases for permissions and existence.
 *
 * This E2E test verifies the correct enforcement of business rules and security for member deletion in the discussion board system.
 *
 * Steps:
 * 1. Register two member accounts: one (as 'target') to be deleted, another (as 'admin') for privileged action requester.
 * 2. Grant the 'admin' member administrative privileges via the admin assignment API.
 * 3. Attempt to delete the 'target' member using the admin account. Validate that the API call succeeds (no error thrown).
 * 4. Try to fetch the deleted member again (should yield a 'not found' or indicate inactive).
 * 5. Attempt to delete a non-existent member by providing a random UUID; expect a 'not found' error.
 * 6. Try to delete a member as another non-admin user: expect forbidden/unauthorized error.
 */
export async function test_api_discussionBoard_test_delete_member_by_admin_and_edge_cases(connection: api.IConnection) {
  // 1. Register the member to be deleted ('target')
  const targetMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(targetMember);

  // 2. Register another member to become admin
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminMember);

  // 3. Grant admin rights to the adminMember
  // Since the API requires both member_id and appointed_by_admin_id, simulate the case where admin appoints themself (for isolated test harness)
  const adminAssignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: adminMember.id,
      appointed_by_admin_id: adminMember.id,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAssignment);

  // 4. Delete the target member as admin
  await api.functional.discussionBoard.members.eraseById(connection, {
    id: targetMember.id,
  });

  // 5. Attempt to "fetch" the target member again by trying to delete again: expect not found error (since no /at endpoint exists in provided APIs)
  TestValidator.error("Deleting an already deleted member should fail")(() =>
    api.functional.discussionBoard.members.eraseById(connection, {
      id: targetMember.id,
    }),
  );

  // 6. Attempt to delete a non-existent member (random UUID): expect not found error
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("Deleting a non-existent member should return not found")(() =>
    api.functional.discussionBoard.members.eraseById(connection, {
      id: nonexistentId,
    }),
  );

  // 7. Register a regular non-admin member
  const nonAdminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(nonAdminMember);

  // 8. Attempt to delete the admin member as a non-admin: expect forbidden/unauthorized error
  // Simulate the non-admin context (no special auth, direct call as if from this user)
  TestValidator.error("Non-admin deletion attempt should fail")(() =>
    api.functional.discussionBoard.members.eraseById(connection, {
      id: adminMember.id,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";
import type { IPageIDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostEdit";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing post edits with pagination, filters, and search parameters.
 *
 * This test simulates a member creating a post within a board, performing multiple edits, and then listing post edits using the paginated filter endpoint. It ensures:
 * - Post edits can be queried using filters for post_id and editor_id.
 * - Pagination returns the correct number of edits per page.
 * - Pagination metadata (current, limit, records, pages) is accurate.
 * - Only relevant edits appear in the response data.
 *
 * Workflow steps:
 * 1. Register a discussion board member who will be the editor.
 * 2. Create a new board.
 * 3. The member creates a post within the board.
 * 4. The member performs several edits of the post, creating a history.
 * 5. List post edits using PATCH /discussionBoard/postEdits with filters for the post and editor, and pagination (limit=2).
 * 6. Validate that the returned data matches the performed edits, respects pagination, and has correct metadata.
 */
export async function test_api_discussionBoard_test_list_post_edits_with_pagination_and_filter(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member (editor)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: "user_" + typia.random<string>(),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: "DisplayName_" + typia.random<string>(),
      password: "Test1234!@#" as string & tags.Format<"password">,
    },
  });
  typia.assert(member);

  // 2. Create a new board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: "Test Board - " + typia.random<string>(),
      slug: "test-board-" + typia.random<string>(),
      description: "Board Description " + typia.random<string>(),
    },
  });
  typia.assert(board);

  // 3. Member creates a post
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: "Test Post Title " + typia.random<string>(),
      body: "This is the original post content. " + typia.random<string>(),
    },
  });
  typia.assert(post);

  // 4. Member performs several edits
  const editPayloads = [
    {
      edit_summary: "Edit 1: typo fix",
      body_after_edit: post.body + " (typo fixed)",
    },
    {
      edit_summary: "Edit 2: improved clarity",
      body_after_edit: post.body + " (clarity improved)",
    },
    {
      edit_summary: "Edit 3: added example",
      body_after_edit: post.body + " (example added)",
    },
  ];
  const edits = [];
  for (const payload of editPayloads) {
    const edit = await api.functional.discussionBoard.postEdits.post(connection, {
      body: {
        post_id: post.id,
        editor_id: member.id,
        edit_summary: payload.edit_summary,
        body_after_edit: payload.body_after_edit,
      },
    });
    typia.assert(edit);
    edits.push(edit);
  }

  // 5. List post edits with patch endpoint, filtering by post_id and editor_id, page 1 with limit 2
  const pageLimit = 2;
  const page1 = await api.functional.discussionBoard.postEdits.patch(connection, {
    body: {
      post_id: post.id,
      editor_id: member.id,
      page: 1,
      limit: pageLimit,
    },
  });
  typia.assert(page1);

  // 6. Validate response contains only the expected edits (paginated)
  TestValidator.equals("pagination limit matches")(page1.pagination.limit)(pageLimit);
  TestValidator.equals("pagination current page")(page1.pagination.current)(1);
  TestValidator.predicate("total records count >= 3")(page1.pagination.records >= 3);
  TestValidator.predicate("data length matches limit or record count")(page1.data.length <= pageLimit && page1.data.length > 0);
  for (const edit of page1.data) {
    TestValidator.equals("post_id matches")(edit.post_id)(post.id);
    TestValidator.equals("editor_id matches")(edit.editor_id)(member.id);
  }
  if (page1.pagination.pages > 1) {
    const page2 = await api.functional.discussionBoard.postEdits.patch(connection, {
      body: {
        post_id: post.id,
        editor_id: member.id,
        page: 2,
        limit: pageLimit,
      },
    });
    typia.assert(page2);
    TestValidator.equals("pagination current page")(page2.pagination.current)(2);
    TestValidator.predicate("data length matches limit or remainder")(page2.data.length <= pageLimit && page2.data.length > 0);
    for (const edit of page2.data) {
      TestValidator.equals("post_id matches")(edit.post_id)(post.id);
      TestValidator.equals("editor_id matches")(edit.editor_id)(member.id);
    }
  }
}

