import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Validate fetching a specific post edit by ID and handling error cases.
 *
 * This test simulates the content audit and revision tracing workflow of the discussion board system:
 *
 *   1. Registers a new member to author and edit a post
 *   2. Creates a new discussion board to house the post
 *   3. Creates a post on the board
 *   4. Submits an edit to the post, generating a post edit record (revision)
 *   5. Fetches the post edit by its ID and verifies all details, confirming correct linkage and content
 *   6. Tries fetching a nonexistent post edit by random UUID, expecting error (e.g., 404)
 *   7. Skips deleted edit fetch test, as the API exposes no post edit deletion functionality
 *
 * This ensures that both standard audit queries and not-found edge cases are correctly implemented in the post edit history and retrieval subsystem.
 */
export async function test_api_discussionBoard_test_get_post_edit_with_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. Register a member for authorship and editing
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.alphabets(6),
    password: RandomGenerator.alphaNumeric(10) as string & tags.Format<"password">,
  };
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a discussion board
  const boardInput: IDiscussionBoardBoard.ICreate = {
    title: RandomGenerator.paragraph()(1, 3),
    slug: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.paragraph()(1, 3),
  };
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a post authored by the member
  const postInput: IDiscussionBoardPost.ICreate = {
    board_id: board.id,
    author_id: member.id,
    title: RandomGenerator.paragraph()(1, 2),
    body: RandomGenerator.content()()(1, 3),
  };
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Submit an edit to the post
  const editInput: IDiscussionBoardPostEdit.ICreate = {
    post_id: post.id,
    editor_id: member.id,
    edit_summary: "Initial typo fix",
    body_after_edit: RandomGenerator.content()()(1, 3),
  };
  const postEdit = await api.functional.discussionBoard.postEdits.post(connection, { body: editInput });
  typia.assert(postEdit);

  // 5. Fetch the post edit by its ID and verify all key fields
  const fetchedEdit = await api.functional.discussionBoard.postEdits.getById(connection, { id: postEdit.id });
  typia.assert(fetchedEdit);
  TestValidator.equals("post edit id matches")(fetchedEdit.id)(postEdit.id);
  TestValidator.equals("post linkage matches")(fetchedEdit.post_id)(post.id);
  TestValidator.equals("editor linkage matches")(fetchedEdit.editor_id)(member.id);
  TestValidator.equals("edit summary matches")(fetchedEdit.edit_summary)(editInput.edit_summary);
  TestValidator.equals("edit content matches")(fetchedEdit.body_after_edit)(editInput.body_after_edit);

  // 6. Negative test: Fetching a random, non-existent edit ID should result in an error
  await TestValidator.error("fetching nonexistent post edit should fail")(async () => {
    await api.functional.discussionBoard.postEdits.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
  // 7. Deleted post edit fetch testing is omitted, as the API provides no delete capability
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Test creation of new post edit records in Discussion Board.
 *
 * This workflow validates three major cases:
 * 1. Happy path (authorized edit): A member edits their own post—the edit is accepted, and all audit fields are correct.
 * 2. Edit a non-existent post: The API should return a validation error when the post_id does not exist.
 * 3. Unauthorized member tries edit: A different user attempts to edit a post they do not own. The system should reject the edit.
 *
 * Steps:
 * 1. Create two unique members (author and stranger).
 * 2. Create a board.
 * 3. Original author creates a post on the board.
 * 4. Author makes a valid edit to the post.
 *    - Confirm response contains correct post_id, editor_id, body_after_edit, and audit fields (id, created_at).
 * 5. Attempt to edit a random/non-existent post_id (by author): Expect validation error.
 * 6. Attempt to edit the real post, but by the stranger member: Expect authorization error.
 */
export async function test_api_discussionBoard_test_create_post_edit_success_and_failure_cases(
  connection: api.IConnection,
) {
  // 1. Create two unique members
  const authorResult = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "AuthorPass123!" as string & tags.Format<"password">,
    },
  });
  typia.assert(authorResult);

  const strangerResult = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Stranger123!" as string & tags.Format<"password">,
    },
  });
  typia.assert(strangerResult);

  // 2. Create a board
  const boardResult = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(9),
      description: RandomGenerator.content()()(),
    },
  });
  typia.assert(boardResult);

  // 3. Author creates a post
  const postResult = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: boardResult.id,
      author_id: authorResult.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(postResult);

  // 4. Author edits their post (happy path)
  const happyEditInput = {
    post_id: postResult.id,
    editor_id: authorResult.id,
    edit_summary: "Fixed typo.",
    body_after_edit: "[EDITED] " + postResult.body,
  } satisfies IDiscussionBoardPostEdit.ICreate;
  const happyEditOutput = await api.functional.discussionBoard.postEdits.post(connection, {
    body: happyEditInput,
  });
  typia.assert(happyEditOutput);
  TestValidator.equals("happy path post_id correct")(happyEditOutput.post_id)(postResult.id);
  TestValidator.equals("editor_id matches author")(happyEditOutput.editor_id)(authorResult.id);
  TestValidator.equals("edit_summary set")(happyEditOutput.edit_summary)(happyEditInput.edit_summary);
  TestValidator.equals("body_after_edit matches")(happyEditOutput.body_after_edit)(happyEditInput.body_after_edit);
  TestValidator.predicate("id is uuid")(!!happyEditOutput.id && happyEditOutput.id.length >= 32);
  TestValidator.predicate("created_at set")(typeof happyEditOutput.created_at === "string");

  // 5. Author tries to edit non-existent post (should fail)
  await TestValidator.error("edit with invalid post_id throws")(
    async () => {
      await api.functional.discussionBoard.postEdits.post(connection, {
        body: {
          post_id: typia.random<string & tags.Format<"uuid">>(),
          editor_id: authorResult.id,
          edit_summary: "Attempt edit non-existent post.",
          body_after_edit: RandomGenerator.content()()(),
        },
      });
    }
  );

  // 6. Stranger attempts to edit real post (should fail)
  await TestValidator.error("stranger cannot edit others' post")(
    async () => {
      await api.functional.discussionBoard.postEdits.post(connection, {
        body: {
          post_id: postResult.id,
          editor_id: strangerResult.id,
          edit_summary: "Trying unauthorized edit.",
          body_after_edit: RandomGenerator.content()()(),
        },
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * Test updating an existing post edit record, covering permission and validation checks
 *
 * This E2E test validates the update workflow for post edit records in the Discussion Board application:
 * - Ensures the original editor can update their own edit summary successfully
 * - Verifies that an unauthorized member cannot update another user's post edit (permission enforcement)
 * - Checks validation for edit summary field (rejects empty string and excessively long summary)
 * - Confirms that only allowed fields (edit_summary, body_after_edit) can be changed and audit fields are preserved
 *
 * Steps:
 * 1. Register two discussion board members (member1 as editor, member2 as unauthorized actor)
 * 2. Create a discussion board
 * 3. Create a post in that board (by member1)
 * 4. Create a post edit record for that post (by member1)
 * 5. Update the edit summary as the original editor (should succeed and change only the allowed field)
 * 6. Attempt update as unauthorized member (should be rejected)
 * 7. Attempt invalid updates (empty summary, overlength summary; both should be rejected)
 */
export async function test_api_discussionBoard_test_update_post_edit_with_permissions_and_validation(
  connection: api.IConnection,
) {
  // 1. Register two members: member1 (editor) and member2 (unauthorized actor)
  const member1Input = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "EditorP@ssw0rd1"
  } satisfies IDiscussionBoardMember.ICreate;
  const member1 = await api.functional.discussionBoard.members.post(connection, { body: member1Input });
  typia.assert(member1);

  const member2Input = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "NotAllowedP@ss2"
  } satisfies IDiscussionBoardMember.ICreate;
  const member2 = await api.functional.discussionBoard.members.post(connection, { body: member2Input });
  typia.assert(member2);

  // 2. Create a discussion board
  const boardInput = {
    title: RandomGenerator.paragraph()(2),
    slug: RandomGenerator.alphaNumeric(12).toLowerCase(),
    description: RandomGenerator.paragraph()(3)
  } satisfies IDiscussionBoardBoard.ICreate;
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a post in that board (by member1)
  const postInput = {
    board_id: board.id,
    author_id: member1.id,
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()()
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Create a post edit record for that post (by member1)
  const originalSummary = "Initial edit for typo correction";
  const postEditInput = {
    post_id: post.id,
    editor_id: member1.id,
    edit_summary: originalSummary,
    body_after_edit: RandomGenerator.content()()()
  } satisfies IDiscussionBoardPostEdit.ICreate;
  const postEdit = await api.functional.discussionBoard.postEdits.post(connection, { body: postEditInput });
  typia.assert(postEdit);

  // 5. Editor successfully updates edit summary (happy path)
  const newSummary = "Editor clarifies rationale for this change.";
  const updatedEdit = await api.functional.discussionBoard.postEdits.putById(connection, {
    id: postEdit.id,
    body: { edit_summary: newSummary } satisfies IDiscussionBoardPostEdit.IUpdate
  });
  typia.assert(updatedEdit);
  TestValidator.equals("summary updated")(updatedEdit.edit_summary)(newSummary);
  TestValidator.equals("editor remains unchanged")(updatedEdit.editor_id)(postEdit.editor_id);
  TestValidator.equals("post_id remains unchanged")(updatedEdit.post_id)(postEdit.post_id);
  TestValidator.equals("created_at is string")(typeof updatedEdit.created_at)("string");

  // 6. Unauthorized member attempts update (should be rejected)
  await TestValidator.error("unauthorized update rejected")(async () => {
    // NOTE: In a real system, you would switch session/context to member2. Here, we simulate the attempt.
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: "Illicit overwrite attempt by non-owner" }
    });
  });

  // 7. Invalid update: empty summary (should be rejected)
  await TestValidator.error("empty edit summary rejected")(async () => {
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: "" }
    });
  });

  // 8. Invalid update: overlong summary (should be rejected)
  await TestValidator.error("edit summary over max length rejected")(async () => {
    await api.functional.discussionBoard.postEdits.putById(connection, {
      id: postEdit.id,
      body: { edit_summary: RandomGenerator.alphaNumeric(600) }
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostEdit";

/**
 * E2E test covering post edit deletion permissions and state edge cases.
 *
 * - Verifies that only the editor or an admin/moderator can delete post edits.
 * - Ensures unauthorized users cannot delete edits.
 * - Tests deletion of already-deleted and non-existent edits.
 * - Validates audit/ownership business rules and ensures output conforms to API contract.
 *
 * Steps:
 * 1. Register 3 members: Editor, Admin/Mod, and Unauthorized User
 * 2. Admin creates a board
 * 3. Editor creates a post in the board
 * 4. Editor creates a post edit
 * 5. Editor deletes their own edit (should succeed)
 * 6. Editor tries to delete same edit again (should fail)
 * 7. Admin creates a post and edit, deletes their own edit (should succeed)
 * 8. Admin deletes a new Editor edit (should succeed)
 * 9. Unauthorized user attempts to delete an edit (should fail)
 * 10. Attempt deletion of non-existent edit as admin (should fail)
 */
export async function test_api_discussionBoard_test_delete_post_edit_authorization_and_states(
  connection: api.IConnection
) {
  // 1. Register Editor
  const editorReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "P@ssw0rd!"
    }
  });
  typia.assert(editorReg);
  const editor = editorReg;

  // 2. Register Admin
  const adminReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Adm1nPass!"
    }
  });
  typia.assert(adminReg);
  const admin = adminReg;

  // 3. Register Unauthorized Member
  const unauthReg = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "UnAuth#123"
    }
  });
  typia.assert(unauthReg);
  const unauthorized = unauthReg;

  // 4. Admin creates board
  // (Assume context identifies creator; board creator is adminReg)
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: `Board ${RandomGenerator.alphabets(6)}`,
      slug: `slug-${RandomGenerator.alphaNumeric(8)}`,
      description: RandomGenerator.paragraph()()
    }
  });
  typia.assert(board);

  // 5. Editor creates post
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: editor.id,
      title: "First Post Title",
      body: RandomGenerator.content()()()
    }
  });
  typia.assert(post);

  // 6. Editor edits post => edit #1
  const postEdit1 = await api.functional.discussionBoard.postEdits.post(connection, {
    body: {
      post_id: post.id,
      editor_id: editor.id,
      body_after_edit: post.body + "\nEdit1",
      edit_summary: "Initial correction"
    }
  });
  typia.assert(postEdit1);

  // 7. Editor deletes their own edit (should succeed)
  const deletedEdit1 = await api.functional.discussionBoard.postEdits.eraseById(connection, {
    id: postEdit1.id
  });
  typia.assert(deletedEdit1);
  TestValidator.equals("deleted edit matches")(deletedEdit1.id)(postEdit1.id);

  // 8. Editor tries to delete same edit again (should fail)
  await TestValidator.error("Cannot delete already-deleted edit")(
    async () => {
      await api.functional.discussionBoard.postEdits.eraseById(connection, {
        id: postEdit1.id
      });
    }
  );

  // 9. Admin creates their own post and edit
  const adminPost = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: admin.id,
      title: "Admin's Post",
      body: RandomGenerator.content()()()
    }
  });
  typia.assert(adminPost);

  const adminEdit = await api.functional.discussionBoard.postEdits.post(connection, {
    body: {
      post_id: adminPost.id,
      editor_id: admin.id,
      body_after_edit: adminPost.body + "\nAdmin Edit",
      edit_summary: "Grammar fix"
    }
  });
  typia.assert(adminEdit);

  // 10. Admin deletes their own edit (should succeed)
  const adminDeletedEdit = await api.functional.discussionBoard.postEdits.eraseById(connection, {
    id: adminEdit.id
  });
  typia.assert(adminDeletedEdit);
  TestValidator.equals("deleted admin post edit")(adminDeletedEdit.id)(adminEdit.id);

  // 11. Editor creates new edit
  const postEdit2 = await api.functional.discussionBoard.postEdits.post(connection, {
    body: {
      post_id: post.id,
      editor_id: editor.id,
      body_after_edit: post.body + "\nEdit2",
      edit_summary: "Substantial update"
    }
  });
  typia.assert(postEdit2);

  // 12. Admin deletes editor's edit (should succeed due to privilege)
  const adminDeletesEditorEdit = await api.functional.discussionBoard.postEdits.eraseById(connection, {
    id: postEdit2.id
  });
  typia.assert(adminDeletesEditorEdit);
  TestValidator.equals("admin deleted editor's edit")(adminDeletesEditorEdit.id)(postEdit2.id);

  // 13. Unauthorized user tries to delete admin edit (should fail)
  await TestValidator.error("Unauthorized cannot delete edits")(
    async () => {
      await api.functional.discussionBoard.postEdits.eraseById(connection, {
        id: adminEdit.id
      });
    }
  );

  // 14. Try deleting a non-existent edit as admin (should fail)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Non-existent edit deletion fails")(
    async () => {
      await api.functional.discussionBoard.postEdits.eraseById(connection, {
        id: fakeId
      });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: Full admin assignment list, filter, and pagination coverage for /discussionBoard/admins
 *
 * This test verifies that administrative assignment listings can be filtered and paginated according to business rules, including edge cases. It tests:
 *
 *  - Creation of a root admin via self-appointment (a business assumption: member[0] appoints themselves as the first admin, as system has no explicit root or superadmin appointment flow)
 *  - Assignment of two further member accounts as admins (by the root admin)
 *  - Status filter ("active"/"revoked") and multi-field filter (by member, by appointing admin, by date range)
 *  - Combination filtering
 *  - Pagination and result set edge cases (no results, out-of-bounds pages)
 *  - Invalid status value rejection
 *
 * Note: As there is no admin revocation API, "revoked" status cannot be dynamically triggered—so status=revoked query tests only that system does not crash, not a real revocation.
 *
 * Steps:
 * 1. Register three members
 * 2. Assign root admin (self-appoint)
 * 3. Assign two more admins (by root admin)
 * 4. Run all major filter/pagination combos and check meta/results
 * 5. Assert appropriate API errors on filter input errors
 */
export async function test_api_discussionBoard_test_list_admin_assignments_with_full_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Register three members for admin assignment eligibility
  const memberInputs = ArrayUtil.repeat(3)(() => ({
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
  }));
  const members = await ArrayUtil.asyncMap(memberInputs)(async body => {
    const member = await api.functional.discussionBoard.members.post(connection, {body});
    typia.assert(member);
    return member;
  });

  // 2. Create root admin (self-appoint). Business assumes member[0] can bootstrap system privileges.
  const rootAdmin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[0].id,
      appointed_by_admin_id: members[0].id,
    },
  });
  typia.assert(rootAdmin);

  // 3. Appoint two further admin assignments by root admin
  const admin1 = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[1].id,
      appointed_by_admin_id: rootAdmin.member_id,
    },
  });
  typia.assert(admin1);

  const admin2 = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: members[2].id,
      appointed_by_admin_id: rootAdmin.member_id,
    },
  });
  typia.assert(admin2);

  // 4a. All assignments (no filters). Ensure all admins present, pagination correct.
  const pageAll = await api.functional.discussionBoard.admins.patch(connection, {body: {}});
  typia.assert(pageAll);
  TestValidator.predicate("all admins present")(
    pageAll.data.some(x => x.id === rootAdmin.id)
    && pageAll.data.some(x => x.id === admin1.id)
    && pageAll.data.some(x => x.id === admin2.id)
  );
  TestValidator.equals("pagination current page")(pageAll.pagination.current)(1);
  TestValidator.predicate("pagination meta valid")(
    pageAll.pagination.limit >= 1 && pageAll.pagination.pages >= 1 && pageAll.pagination.records >= 3
  );

  // 4b. Active admins filter (status="active")
  const pageActive = await api.functional.discussionBoard.admins.patch(connection, {body: {status: "active"}});
  typia.assert(pageActive);
  TestValidator.predicate("all returned active")(
    pageActive.data.every(x => x.revoked_at == null)
  );

  // 4c. Revoked admins filter (status="revoked")
  const pageRevoked = await api.functional.discussionBoard.admins.patch(connection, {body: {status: "revoked"}});
  typia.assert(pageRevoked);
  TestValidator.predicate("all returned revoked")(
    pageRevoked.data.every(x => x.revoked_at != null)
  );

  // 4d. member_id filter (assignment for one member)
  const pageByMember = await api.functional.discussionBoard.admins.patch(connection, {body: {member_id: admin1.member_id}});
  typia.assert(pageByMember);
  TestValidator.predicate("by member_id only")(
    pageByMember.data.every(x => x.member_id === admin1.member_id)
  );

  // 4e. appointed_by_admin_id filter (assignments by root admin)
  const pageByAppointer = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_by_admin_id: rootAdmin.member_id}});
  typia.assert(pageByAppointer);
  TestValidator.predicate("by appointed_by_admin_id only")(
    pageByAppointer.data.every(x => x.appointed_by_admin_id === rootAdmin.member_id)
  );

  // 4f. appointed_from filter: select using admin2's appointed_at as lower bound
  const pageByAppointedFrom = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_from: admin2.appointed_at}});
  typia.assert(pageByAppointedFrom);
  TestValidator.predicate("all appointed_at >= filter")(
    pageByAppointedFrom.data.every(x => x.appointed_at >= admin2.appointed_at)
  );

  // 4f. appointed_to filter: admin2's timestamp as upper bound
  const pageByAppointedTo = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_to: admin2.appointed_at}});
  typia.assert(pageByAppointedTo);
  TestValidator.predicate("all appointed_at <= filter")(
    pageByAppointedTo.data.every(x => x.appointed_at <= admin2.appointed_at)
  );

  // 4g. Combination filter: status + appointed_by_admin_id
  const pageCombo = await api.functional.discussionBoard.admins.patch(connection, {body: {appointed_by_admin_id: rootAdmin.member_id, status: "active"}});
  typia.assert(pageCombo);
  TestValidator.predicate("all combo matched")(
    pageCombo.data.every(x => x.appointed_by_admin_id === rootAdmin.member_id && x.revoked_at == null)
  );

  // 4h. Pagination test, limit=1, page=2
  const pageLimited = await api.functional.discussionBoard.admins.patch(connection, {body: {limit: 1, page: 2}});
  typia.assert(pageLimited);
  TestValidator.equals("pagination limit is 1")(pageLimited.pagination.limit)(1);
  TestValidator.equals("pagination page is 2")(pageLimited.pagination.current)(2);
  // It's possible last page will be empty due to total # admins; just check .data is an array
  TestValidator.predicate("pagination page has results or empty")(
    Array.isArray(pageLimited.data)
  );

  // 4i. Out-of-bounds page: page number > pages returns empty data
  const pageOob = await api.functional.discussionBoard.admins.patch(connection, {body: {limit: 1, page: 100}});
  typia.assert(pageOob);
  TestValidator.equals("pagination out of bounds is empty")(
    pageOob.data.length
  )(0);

  // 5. Invalid status filter (non-enum): should throw error
  await TestValidator.error("invalid status enum")(() =>
    api.functional.discussionBoard.admins.patch(connection, {body: {status: "invalid" as any}})
  );
}

