  TestValidator.equals('appointed_at')(getAdminB.appointed_at)(adminAssignB.appointed_at);
  TestValidator.equals('revoked_at')(getAdminB.revoked_at)(adminAssignB.revoked_at);

  // 5. Try retrieving with a non-existent/random UUID; expect 404
  await TestValidator.error('404 on non-existent ID')(async () => {
    await api.functional.discussionBoard.admins.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>()
    });
