/**
 * Test admin creation of a new admin assignment for a member.
 *
 * Purpose: End-to-end validation of the administrator assignment workflow, including positive and negative paths.
 * Ensures that only eligible members can be promoted by existing admins, role uniqueness and business rules are enforced,
 * and that failures due to invalid operations produce correct error responses.
 *
 * Steps:
 * 1. Register two normal user members (candidate1, candidate2)
 * 2. Register a bootstrap system admin (admin1) who will act as assignor
 * 3. Assign admin role to candidate1 (expect success, check data)
 * 4. Attempt assignment to non-existent member (expect error)
 * 5. Attempt duplicate admin assignment for candidate1 (expect error)
 * 6. Attempt to assign an admin using a non-admin (candidate2 as assignor, expect forbidden)
 *  - Note: Skips explicit audit log validation as there is no exposed endpoint
 */
export async function test_api_discussionBoard_test_create_admin_assignment_for_eligible_and_ineligible_members(
  connection: api.IConnection,
) {
  // 1. Register candidate1
  const candidate1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(candidate1);

  // 2. Register candidate2
  const candidate2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(candidate2);

  // 3. Register admin1 (bootstrapping a system admin)
  const admin1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin1);

  // Manually assign admin1 as initial admin (bypass: this is needed in real infra)
  // For test: assign admin role using system self—appointing
  const bootstrapAdmin = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: admin1.id,
      appointed_by_admin_id: admin1.id,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(bootstrapAdmin);
  TestValidator.equals("admin1 assigned to self")(bootstrapAdmin.member_id)(admin1.id);

  // 4. Admin1 assigns admin role to candidate1
  const adminAssignment = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: candidate1.id,
      appointed_by_admin_id: admin1.id,
    } satisfies IDiscussionBoardAdmin.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("candidate1 is admin")(adminAssignment.member_id)(candidate1.id);
  TestValidator.equals("appointing admin reference")(adminAssignment.appointed_by_admin_id)(admin1.id);
  TestValidator.predicate("has appointment timestamp")(typeof adminAssignment.appointed_at === "string" && adminAssignment.appointed_at.length > 0);
  TestValidator.equals("not revoked")(adminAssignment.revoked_at)(null);

  // 5. Failure: assign admin to non-existent random member
  await TestValidator.error("fail on non-existent member")(async () => {
    await api.functional.discussionBoard.admins.post(connection, {
      body: {
        member_id: typia.random<string & tags.Format<"uuid">>(),
        appointed_by_admin_id: admin1.id,
      } satisfies IDiscussionBoardAdmin.ICreate,
    });
  });

  // 6. Failure: duplicate admin assignment for candidate1
  await TestValidator.error("fail on duplicate admin")(async () => {
    await api.functional.discussionBoard.admins.post(connection, {
      body: {
        member_id: candidate1.id,
        appointed_by_admin_id: admin1.id,
      } satisfies IDiscussionBoardAdmin.ICreate,
