  const memberC = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    },
  });
  typia.assert(memberC);

  // 2. Bootstrap admin privilege by self-appointing memberA (first admin)
  const adminA = await api.functional.discussionBoard.admins.post(connection, {
    body: {
      member_id: memberA.id,
      appointed_by_admin_id: memberA.id,
    },
  });
  typia.assert(adminA);

  // 3. Assign admin role to memberB using memberA
  const adminB = await api.functional.discussionBoard.admins.post(connection, {
