import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReportCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportCategory";
import type { IPageIDiscussionBoardReportCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReportCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieval of a paginated and filtered list of report categories for moderation workflows.
 *
 * This test ensures that moderators or admins can retrieve a paginated and searched list
 * of report categories for moderation through the PATCH /discussionBoard/reportCategories endpoint.
 * The test validates search queries, pagination, boundary handling, and authorization.
 *
 * Steps:
 * 1. As an authenticated moderator, request a report category list (e.g., page 1, limit 2) without a search filter.
 * 2. Verify that the result includes the correct pagination metadata (current page, limit, records, pages).
 * 3. Perform a search query using a filter like 'spam', check that only relevant categories are returned.
 * 4. Repeat with a search query that yields no matches (e.g., gibberish), and verify results are empty but pagination metadata is valid.
 * 5. Attempt to access the endpoint as an unauthorized (non-admin/moderator) user and verify access is denied.
 */
export async function test_api_discussionBoard_test_list_report_categories_with_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. As an authenticated moderator, request page 1 of report categories
  const page1 = await api.functional.discussionBoard.reportCategories.patch(
    connection,
    { body: { page: 1, limit: 2 } satisfies IDiscussionBoardReportCategory.IRequest },
  );
  typia.assert(page1);
  TestValidator.predicate("page1 has correct pagination")(
    page1.pagination.current === 1 &&
    page1.pagination.limit === 2 &&
    page1.data.length <= 2
  );

  // 2. Perform a search query for 'spam'
  const searchSpam = await api.functional.discussionBoard.reportCategories.patch(
    connection,
    { body: { query: "spam", page: 1, limit: 10 } satisfies IDiscussionBoardReportCategory.IRequest },
  );
  typia.assert(searchSpam);
  TestValidator.predicate("only categories containing 'spam'")(
    searchSpam.data.every(cat => cat.name.toLowerCase().includes("spam"))
  );

  // 3. Empty search query (gibberish)
  const gibberish = "nonexistentcategory12345";
  const emptySearch = await api.functional.discussionBoard.reportCategories.patch(
    connection,
    { body: { query: gibberish, page: 1, limit: 10 } satisfies IDiscussionBoardReportCategory.IRequest },
  );
  typia.assert(emptySearch);
  TestValidator.equals("no matches for nonsense search")(emptySearch.data.length)(0);
  TestValidator.predicate("pagination valid for empty result")(
    emptySearch.pagination.current === 1 &&
    emptySearch.pagination.limit === 10 &&
    emptySearch.pagination.records === 0 &&
    emptySearch.pagination.pages === 0
  );

  // 4. Attempt with unauthorized user (simulate by clearing auth or using low-privilege connection)
  const unauthorizedConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized users cannot retrieve report categories")(
