/**
 * Test conditional deletion (withdrawal) of a moderation appeal decision.
 *
 * This scenario verifies that only the original actor (moderator or admin) can delete their own moderation appeal decision prior to finalization/lock, and that attempts by non-owners, after finalization, or for non-existent decisions are properly forbidden or error-handled. Also ensures soft-deletion with audit trail preservation where supported.
 *
 * Steps:
 * 1. Create a moderation appeal via POST /discussionBoard/moderationAppeals as a normal member.
 * 2. As a moderator, POST /discussionBoard/appealDecisions to record a decision for the appeal, recording who made it.
 * 3. Attempt to DELETE /discussionBoard/appealDecisions/{id} as the original actor before any finalization/lock. Expect success.
 * 4. Re-create a new decision for the same appeal by a different moderator.
 * 5. Attempt DELETE as non-owner (should be forbidden).
 * 6. Attempt DELETE a non-existent (random UUID) decision; expect not found.
 * 7. Omit finalization/lock test since such state is not defined in the DTO/API provided.
 */
export async function test_api_discussionBoard_test_delete_appeal_decision_by_authorized_actor_only_with_finalization_constraints(
  connection: api.IConnection,
) {
  // 1. Create moderation appeal (simulate member)
  const member_id = typia.random<string & tags.Format<"uuid">>();
  const moderation_action_id = typia.random<string & tags.Format<"uuid">>();
  const appeal = await api.functional.discussionBoard.moderationAppeals.post(connection, {
    body: {
      moderation_action_id,
      member_id,
      appeal_reason: "I believe this action was unjustified."
    } satisfies IDiscussionBoardModerationAppeal.ICreate
  });
  typia.assert(appeal);

  // 2. As moderator, create appeal decision
  const moderator_id_1 = typia.random<string & tags.Format<"uuid">>();
  const decision = await api.functional.discussionBoard.appealDecisions.post(connection, {
    body: {
      appeal_id: appeal.id,
      moderator_id: moderator_id_1,
      decision_outcome: "upheld",
      decision_rationale: "Action followed policy."
    } satisfies DiscussionBoardAppealDecision.ICreate
  });
  typia.assert(decision);

  // 3. DELETE as original actor (moderator)
  const deletedDecision = await api.functional.discussionBoard.appealDecisions.eraseById(connection, {
    id: decision.id
  });
  typia.assert(deletedDecision);
  TestValidator.equals("deleted decision id")(deletedDecision.id)(decision.id);
  // (Soft-delete verification: if schema supported visible flag, it could be asserted here)

  // 4. Create a new appeal decision for the same appeal, by another moderator
  const moderator_id_2 = typia.random<string & tags.Format<"uuid">>();
  const decision2 = await api.functional.discussionBoard.appealDecisions.post(connection, {
    body: {
      appeal_id: appeal.id,
      moderator_id: moderator_id_2,
      decision_outcome: "overturned",
      decision_rationale: "Additional evidence provided."
    } satisfies DiscussionBoardAppealDecision.ICreate
  });
  typia.assert(decision2);

  // 5. Attempt DELETE as a non-owner (should fail)
  await TestValidator.error("non-owner cannot delete")(() =>
    api.functional.discussionBoard.appealDecisions.eraseById(connection, {
      id: decision2.id
    })
  );

  // 6. Attempt DELETE non-existent decision (should fail)
  await TestValidator.error("delete non-existent decision fails")(() =>
    api.functional.discussionBoard.appealDecisions.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>()
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing, filtering, and pagination of discussion board comments.
 *
 * Scenario:
 *  1. Register two members (author1 and author2).
 *  2. Register a board.
 *  3. Author1 posts to the board.
 *  4. Authors create multiple comments across varying depth, thread, and edit status.
 *  5. List comments using POST /discussionBoard/comments.patch with various filters:
 *     - By post_id
 *     - By thread_id
 *     - By author_id
 *     - By is_edited
 *     - By depth or depth ranges
 *     - By created date or updated date range
 *  6. Confirm pagination works; check total, page/limit, and slicing.
 *  7. Mark one comment as soft deleted and verify regular user cannot see it (is_deleted=false by default).
 *  8. Query with is_deleted=true as admin to confirm deleted comment is visible.
 *  9. Try invalid filters (non-existent post_id, malformed uuid, invalid page) and expect errors.
 */
export async function test_api_discussionBoard_test_list_comments_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register member1 (author1)
  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(10),
    },
  });
  typia.assert(member1);

  // Register member2 (author2)
  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(10),
    },
  });
  typia.assert(member2);

  // 2. Register a board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.alphabets(12),
      slug: RandomGenerator.alphaNumeric(16),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(board);

  // 3. Author1 creates a post
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member1.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Authors write comments to this post in various configurations (depth, nesting, authorship, edit status)
  // Root comment by member1
  const comment_root1 = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: member1.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    },
  });
  typia.assert(comment_root1);

  // Root comment by member2
  const comment_root2 = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: member2.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    },
  });
  typia.assert(comment_root2);

  // Nested reply to root1 by member2 (depth=1)
  const comment_reply_1 = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: comment_root1.id,
      author_id: member2.id,
      body: RandomGenerator.paragraph()(),
      depth: 1,
    },
  });
  typia.assert(comment_reply_1);

  // Nested reply to root2 by member1 (depth=1)
  const comment_reply_2 = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: comment_root2.id,
      author_id: member1.id,
      body: RandomGenerator.paragraph()(),
      depth: 1,
    },
  });
  typia.assert(comment_reply_2);

  // Deep nested reply to reply_1 by member1 (depth=2)
  const comment_reply_1_2 = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: post.id,
      thread_id: comment_reply_1.id,
      author_id: member1.id,
      body: RandomGenerator.paragraph()(),
      depth: 2,
    },
  });
  typia.assert(comment_reply_1_2);

  // Mark the last comment as edited (simulate by updating is_edited property directly disables, but for testing: use created_at/updated_at filter to infer edit)

  // 5. List comments by post_id
  const by_post = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      post_id: post.id,
    },
  });
  typia.assert(by_post);
  TestValidator.predicate("all are for this post")(by_post.data.every(c => c.post_id === post.id));

  // 6. List by author_id (member1)
  const by_author = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      author_id: member1.id,
    },
  });
  typia.assert(by_author);
  TestValidator.predicate("all from author1")(by_author.data.every(c => c.author_id === member1.id));

  // 7. List by thread_id (root1, should include its direct child)
  const by_thread = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      thread_id: comment_root1.id,
    },
  });
  typia.assert(by_thread);
  TestValidator.predicate("thread == root1")(by_thread.data.every(c => c.thread_id === comment_root1.id));

  // 8. List by depth (depth=0, root-level)
  const by_depth0 = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      depth_min: 0,
      depth_max: 0,
    },
  });
  typia.assert(by_depth0);
  TestValidator.predicate("all depth 0")(by_depth0.data.every(c => c.depth === 0));

  // 9. List by is_edited (all should be false as created)
  const by_edited_false = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      is_edited: false,
    },
  });
  typia.assert(by_edited_false);
  TestValidator.predicate("all not edited")(by_edited_false.data.every(c => c.is_edited === false));

  // 10. List by created_at/updated_at range (from before creation, should include all)
  const from_time = new Date(Date.now() - 1000 * 60 * 60).toISOString();
  const to_time = new Date(Date.now() + 1000 * 60 * 60).toISOString();
  const by_time = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      created_at_from: from_time,
      created_at_to: to_time,
      updated_at_from: from_time,
      updated_at_to: to_time,
    },
  });
  typia.assert(by_time);
  TestValidator.predicate("in time range")(by_time.data.every(
    c => c.created_at >= from_time && c.created_at <= to_time && c.updated_at >= from_time && c.updated_at <= to_time
  ));

  // 11. Pagination - limit=2
  const by_limit = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      post_id: post.id,
      limit: 2,
      page: 1,
    },
  });
  typia.assert(by_limit);
  TestValidator.equals("page size == 2")(by_limit.data.length)(2);
  TestValidator.equals("current page 1")(by_limit.pagination.current)(1);
  TestValidator.equals("limit 2")(by_limit.pagination.limit)(2);
  TestValidator.predicate("first 2 slice")(by_limit.data.length <= 2);

  // 12. Soft-delete simulation: set deleted_at on comment_reply_2 (simulate by remembering id and filtering on is_deleted)
  // Since no update/delete endpoint, simulate only query check
  // Query with is_deleted=false (should omit soft deleted), and is_deleted=true

  // As normal user, confirm deleted_at==null only (should not include soft-deleted comments)
  const by_not_deleted = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      post_id: post.id,
      is_deleted: false,
    },
  });
  typia.assert(by_not_deleted);
  TestValidator.predicate("no soft deleted")(by_not_deleted.data.every(c => !c.deleted_at));

  // As admin, if such user, request with is_deleted=true - should include any soft-deleted comments if they existed
  // (cannot actually soft-delete here, but logic allows for query)
  const by_deleted = await api.functional.discussionBoard.comments.patch(connection, {
    body: {
      post_id: post.id,
      is_deleted: true,
    },
  });
  typia.assert(by_deleted);
  TestValidator.predicate("all soft deleted")(by_deleted.data.every(c => !!c.deleted_at));

  // 13. Negative case: non-existent post_id
  TestValidator.error("non-existent post")(async () => {
    await api.functional.discussionBoard.comments.patch(connection, {
      body: {
        post_id: typia.random<string & tags.Format<"uuid">>(),
      },
    });
  });

  // 14. Negative case: malformed uuid
  TestValidator.error("malformed uuid")(async () => {
    await api.functional.discussionBoard.comments.patch(connection, {
      body: {
        post_id: "bad-uuid-format" as any,
      },
    });
  });

  // 15. Negative case: invalid page number (e.g., -1)
  TestValidator.error("invalid page number")(async () => {
    await api.functional.discussionBoard.comments.patch(connection, {
      body: {
        post_id: post.id,
        page: -1 as any,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
