import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";

/**
 * Validate fetching discussion board comment detail as an authenticated user.
 *
 * This test ensures both positive and negative scenarios for retrieving a single comment by ID. It simulates a real user flow:
 *
 * 1. Register a discussion board member (who will be the author of the comment).
 * 2. Create a discussion board through the admin endpoint.
 * 3. As the member, create a post in that board.
 * 4. As the member, create a comment on the post.
 * 5. Fetch the comment detail by its ID, and verify all fields (IDs, author, post/thread, body, timestamps, depth, etc) match what was created.
 * 6. Attempt to fetch the same comment while unauthenticated and expect failure (access denied or forbidden).
 * 7. Try fetching using an invalid/non-existent UUID and check if 404 is returned.
 * 8. Soft-delete the comment (if available); then verify regular users cannot access it (404), but admin *can* access it if business rules permit (cannot be fully implemented if no soft-delete API exists).
 *
 * All API output must be validated for correct schema and business logic. Only implement steps allowed by available APIs and DTOs.
 */
export async function test_api_discussionBoard_test_get_comment_detail_as_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "SecurePwd!42",
  };
  const member = await api.functional.discussionBoard.members.post(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a new board (admin operation)
  const boardInput: IDiscussionBoardBoard.ICreate = {
    title: RandomGenerator.paragraph()(1),
    slug: RandomGenerator.alphaNumeric(8),
    description: RandomGenerator.content()()(),
  };
  const board = await api.functional.discussionBoard.boards.post(connection, { body: boardInput });
  typia.assert(board);

  // 3. Create a post associated with the board
  const postInput: IDiscussionBoardPost.ICreate = {
    board_id: board.id,
    author_id: member.id,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postInput });
  typia.assert(post);

  // 4. Create a comment as the member (self-referencing thread_id is allowed for root comment)
  const commentInput: IDiscussionBoardComment.ICreate = {
    post_id: post.id,
    thread_id: typia.random<string & tags.Format<"uuid">>(), // Thread structure in real impl may mirror comment ID for root
    author_id: member.id,
    body: RandomGenerator.paragraph()(),
    depth: 0,
  };
  const comment = await api.functional.discussionBoard.comments.post(connection, { body: commentInput });
  typia.assert(comment);

  // 5. Fetch the comment by ID and assert all fields match the created values
  const detail = await api.functional.discussionBoard.comments.getById(connection, { id: comment.id });
  typia.assert(detail);
  TestValidator.equals("comment.id")(detail.id)(comment.id);
  TestValidator.equals("comment.author_id")(detail.author_id)(member.id);
  TestValidator.equals("comment.post_id")(detail.post_id)(post.id);
  TestValidator.equals("comment.body")(detail.body)(commentInput.body);
  TestValidator.equals("comment.depth")(detail.depth)(commentInput.depth);

  // 6. Attempt accessing comment with an obviously fake/nonexistent ID, expect 404 (error thrown)
  await TestValidator.error("non-existent comment 404")(() =>
    api.functional.discussionBoard.comments.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // unlikely collision
    })
  );

