import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";

/**
 * Validate failure when creating a Discussion Board Channel with a duplicate name.
 *
 * Business context: The discussion board platform requires that each channel name must be unique across the system to avoid ambiguity in navigation and channel management. If an admin attempts to create a new channel using a name that already exists (even if the other fields such as description differ), the API must enforce the database uniqueness constraint on the discussionboard_channels.name column. The API should return a conflict error in this situation (typically 409).
 *
 * Steps:
 * 1. Successfully create a new channel with a unique name.
 * 2. Attempt to create a second channel using the same name but (optionally) a different description. 
 * 3. Assert that an error occurs due to the uniqueness violation.
 * 4. Optionally verify that the error code/status matches the expected (usually 409 Conflict), and the error message indicates duplication.
 */
export async function test_api_discussionBoard_test_create_channel_with_duplicate_name_conflict(
  connection: api.IConnection,
) {
  // 1. Successfully create a channel with a unique name
  const baseName = RandomGenerator.alphaNumeric(12);
  const firstChannel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: baseName,
      description: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(firstChannel);
  TestValidator.equals("channel name matches")(firstChannel.name)(baseName);

  // 2. Attempt to create another channel with the same name
  await TestValidator.error("should fail with duplicate channel name")(
    async () => {
      await api.functional.discussionBoard.channels.post(connection, {
        body: {
          name: baseName, // duplicate name triggers uniqueness violation
          description: RandomGenerator.content()()(),
        } satisfies IDiscussionBoardChannel.ICreate,
      });
    },
  );
}

