import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardChannel";

/**
 * Validate updating selected attributes of an existing discussion board channel as an admin user.
 *
 * This test simulates a realistic scenario for updating the name and description of a discussion board channel by an admin user.
 * It ensures:
 * - The update endpoint respects business rules, such as channel name uniqueness and correct handling of nullable/optional properties.
 * - Patch/partial updates work as intended (fields can be updated independently, null skips property).
 * - Input is normalized by trimming whitespace (leading/trailing) for name and description.
 * - Timestamps (updated_at) are properly managed after update.
 * - Error cases are handled correctly: duplicate (non-unique) names are rejected and invalid UUIDs cause an error.
 *
 * Step-by-step process:
 * 1. Create an initial channel for updating (dependency).
 * 2. Create a second distinct channel to enable unique name constraint checks.
 * 3. Update the first channel's name and description with new values and confirm success.
 * 4. Attempt to change the first channel's name to the second's (expect unique constraint error).
 * 5. Update with leading/trailing spaces to check normalization (expect auto-trimming).
 * 6. Partial update (update only description, confirm name stays the same).
 * 7. Patch with nulls to skip update (confirm fields unchanged).
 * 8. Attempt update with invalid UUID (expect error).
 * 9. Confirm key fields and invariants unchanged where appropriate.
 */
export async function test_api_discussionBoard_test_update_channel_attributes_success_by_admin(
  connection: api.IConnection,
) {
  // 1. Create an initial channel for update dependency
  const initialChannel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: `Channel_${RandomGenerator.alphabets(10)}`,
      description: "This is the initial test channel.",
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(initialChannel);

  // 2. Create a second channel for uniqueness/duplicate check
  const otherChannel = await api.functional.discussionBoard.channels.post(connection, {
    body: {
      name: `Another_${RandomGenerator.alphaNumeric(10)}`,
      description: "Another channel for uniqueness checks.",
    } satisfies IDiscussionBoardChannel.ICreate,
  });
  typia.assert(otherChannel);

  // 3. Update channel: change name and description
  const updatedName = `Updated_${RandomGenerator.alphaNumeric(8)}`;
  const updatedDescription = "E2E updated channel description.";
  const updateRes = await api.functional.discussionBoard.channels.putById(connection, {
    id: initialChannel.id,
    body: {
      name: updatedName,
      description: updatedDescription,
    } satisfies IDiscussionBoardChannel.IUpdate,
  });
  typia.assert(updateRes);
  TestValidator.equals("name updated")(updateRes.name)(updatedName);
  TestValidator.equals("description updated")(updateRes.description)(updatedDescription);
  TestValidator.notEquals("updated_at has changed")(updateRes.updated_at)(initialChannel.updated_at);

  // 4. Try to update to a duplicate name (unique constraint)
  await TestValidator.error("duplicate name rejected")(async () => {
    await api.functional.discussionBoard.channels.putById(connection, {
      id: initialChannel.id,
      body: {
        name: otherChannel.name,
      }
    });
  });

  // 5. Update using whitespace-padded values (check normalization/auto-trim)
  const spacedName = `  ${RandomGenerator.alphaNumeric(7)}  `;
  const spacedDesc = `  ${RandomGenerator.paragraph()(1)}  `;
  const normRes = await api.functional.discussionBoard.channels.putById(connection, {
    id: initialChannel.id,
    body: {
      name: spacedName,
      description: spacedDesc,
    } satisfies IDiscussionBoardChannel.IUpdate,
  });
  typia.assert(normRes);
  TestValidator.equals("name normalized")(normRes.name)(spacedName.trim());
  TestValidator.equals("description normalized")(normRes.description)(spacedDesc.trim());

  // 6. Patch: update only 'description' (should remain name)
  const descUpdate = "Patch-only description.";
  const patchRes = await api.functional.discussionBoard.channels.putById(connection, {
    id: initialChannel.id,
    body: {
      description: descUpdate,
    } satisfies IDiscussionBoardChannel.IUpdate,
  });
  typia.assert(patchRes);
  TestValidator.equals("description patched")(patchRes.description)(descUpdate);
  TestValidator.equals("name remains on patch")(patchRes.name)(normRes.name);

  // 7. Explicit null fields: send null for name & description (should not update)
  const skipNullRes = await api.functional.discussionBoard.channels.putById(connection, {
    id: initialChannel.id,
    body: {
      name: null,
      description: null,
    } satisfies IDiscussionBoardChannel.IUpdate,
  });
  typia.assert(skipNullRes);
  TestValidator.equals("name remains after null")(skipNullRes.name)(patchRes.name);
  TestValidator.equals("description remains after null")(skipNullRes.description)(patchRes.description);

  // 8. Negative scenario: invalid UUID format
  await TestValidator.error("invalid id format rejected")(async () => {
    await api.functional.discussionBoard.channels.putById(connection, {
      id: "invalid-uuid" as any,
      body: {
        name: `X_${RandomGenerator.alphaNumeric(6)}`,
      },
    });
  });

  // 9. Confirm id/created_at are unchanged after all updates
  TestValidator.equals("channel id stable")(skipNullRes.id)(initialChannel.id);
  TestValidator.equals("created_at stable")(skipNullRes.created_at)(initialChannel.created_at);
}

