import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostSnapshot";
import type { IPageIDiscussionBoardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieval of discussion board post snapshots with various filters and pagination options.
 *
 * This test validates that the postSnapshots PATCH endpoint correctly returns a paginated list of post snapshots filtered by post ID, creator ID, and date range. The test sets up prerequisite data by creating a member, a board, a post, and at least one snapshot.
 *
 * Test procedure:
 * 1. Create a member (for acting as post author and snapshot creator)
 * 2. Create a board (for associating the post)
 * 3. Create a post (linked to member and board)
 * 4. Create two snapshots on the post (with slightly different timestamps/creators)
 * 5. Query for post snapshots:
 *    a. Filter by post_id: verify only snapshots of this post are returned
 *    b. Filter by created_by_id: verify only snapshots by this member are returned
 *    c. Filter by created_from/created_to: verify only snapshots within range are returned
 *    d. Test pagination (limit=1): verify correct paging and result counts
 *
 * Each response is validated for correct data filtering, result structure, and consistent pagination metadata.
 */
export async function test_api_discussionBoard_test_search_post_snapshots_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "password1234" as string & tags.Format<"password">,
    },
  });
  typia.assert(member);

  // 2. Create a board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(board);

  // 3. Create a post by the member on the board
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 4. Create two snapshots for the post
  const snapshot1 = await api.functional.discussionBoard.postSnapshots.post(connection, {
    body: {
      post_id: post.id,
      created_by_id: member.id,
      title: post.title,
      body: post.body,
    },
  });
  typia.assert(snapshot1);

  // Optionally wait 1 second to ensure a different created_at for snapshot2
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const snapshot2 = await api.functional.discussionBoard.postSnapshots.post(connection, {
    body: {
      post_id: post.id,
      created_by_id: member.id,
      title: post.title + " updated",
      body: post.body + " revision 2",
    },
  });
  typia.assert(snapshot2);

  // 5.a. Filter by post_id
  const resultByPostId = await api.functional.discussionBoard.postSnapshots.patch(connection, {
    body: {
      post_id: post.id,
    },
  });
  typia.assert(resultByPostId);
  for (const snap of resultByPostId.data) {
    TestValidator.equals("snapshot post_id matches filter")(snap.post_id)(post.id);
  }

  // 5.b. Filter by created_by_id
  const resultByCreator = await api.functional.discussionBoard.postSnapshots.patch(connection, {
    body: {
      created_by_id: member.id,
    },
  });
  typia.assert(resultByCreator);
  for (const snap of resultByCreator.data) {
    TestValidator.equals("snapshot creator matches filter")(snap.created_by_id)(member.id);
  }

  // 5.c. Filter by date range
  // (use the created_at of snapshot1 and snapshot2)
  const startTime = snapshot1.created_at;
  const endTime = snapshot2.created_at;
  const resultByDate = await api.functional.discussionBoard.postSnapshots.patch(connection, {
    body: {
      created_from: startTime,
      created_to: endTime,
    },
  });
  typia.assert(resultByDate);
  for (const snap of resultByDate.data) {
    TestValidator.predicate("snapshot in range")(
      snap.created_at >= startTime && snap.created_at <= endTime,
    );
  }

  // 5.d. Pagination: limit=1, page=1
  const pagedResult1 = await api.functional.discussionBoard.postSnapshots.patch(connection, {
    body: {
      post_id: post.id,
      limit: 1,
      page: 1,
    },
  });
  typia.assert(pagedResult1);
  TestValidator.equals("pagination limit")(pagedResult1.data.length)(1);
  TestValidator.equals("pagination page")(pagedResult1.pagination.current)(1);

  // 5.d. Pagination: limit=1, page=2
  const pagedResult2 = await api.functional.discussionBoard.postSnapshots.patch(connection, {
    body: {
      post_id: post.id,
      limit: 1,
      page: 2,
    },
  });
  typia.assert(pagedResult2);
  TestValidator.equals("pagination limit")(pagedResult2.data.length)(1);
  TestValidator.equals("pagination page")(pagedResult2.pagination.current)(2);
  TestValidator.equals("pagination records")(pagedResult2.pagination.limit)(1);

  // Assert that paged results are distinct
  if (pagedResult1.data.length === 1 && pagedResult2.data.length === 1) {
    TestValidator.notEquals("paged results distinct")(
      pagedResult1.data[0].id,
    )(pagedResult2.data[0].id);
  }
}

