import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBoard";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostSnapshot";
import type { IPageIDiscussionBoardPostSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that searching (listing) post snapshots does not return soft-deleted snapshots.
 *
 * This test simulates the flow:
 * 1. Create a discussion board member for snapshot creation.
 * 2. Create a discussion board.
 * 3. Create a post on the discussion board by the member.
 * 4. Create a post snapshot for that post.
 * 5. Soft-delete the created post snapshot.
 * 6. List/search post snapshots for that post.
 * 7. Validate that the deleted snapshot does not appear in the result set.
 *
 * - Business purpose: ensure soft-deleted/archived snapshots are hidden from query results for regular users.
 * - This validates proper exclusion of deleted items, complying with business and audit rules.
 */
export async function test_api_discussionBoard_test_search_post_snapshots_excludes_deleted_entries(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (who will create the snapshot)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "test-password-123",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Set up a discussion board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Create a post for snapshots
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a post snapshot of the post
  const snapshot = await api.functional.discussionBoard.postSnapshots.post(connection, {
    body: {
      post_id: post.id,
      created_by_id: member.id,
      title: post.title,
      body: post.body,
    } satisfies IDiscussionBoardPostSnapshot.ICreate,
  });
  typia.assert(snapshot);

  // 5. Soft-delete (archive) the created snapshot
  const deletedSnapshot = await api.functional.discussionBoard.postSnapshots.eraseById(connection, {
    id: snapshot.id,
  });
  typia.assert(deletedSnapshot);

  // 6. List/search post snapshots (should not include deleted snapshot)
  const searchResult = await api.functional.discussionBoard.postSnapshots.patch(connection, {
    body: {
      post_id: post.id,
    },
  });
  typia.assert(searchResult);

  // 7. Assert that the deleted snapshot does not appear in the results
  const snapshotIds = searchResult.data.map((s) => s.id);
  TestValidator.predicate("Deleted snapshot is excluded")(snapshotIds.includes(snapshot.id) === false);
}

