 * 5. Update the snapshot's title and body.
 * 6. Verify that the update is reflected in the returned snapshot, including all immutable audit fields.
 *
 * Notes:
 * - As IDiscussionBoardPostSnapshot only includes created_at (not updated_at), this test confirms created_at remains unchanged after update, per audit policy.
 * - Only fields permitted by the DTO are accessed and checked.
 */
export async function test_api_discussionBoard_test_update_post_snapshot_successful(
  connection: api.IConnection
) {
  // 1. Create a discussion board member (author)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphabets(12) as string & tags.Format<"password">,
    },
  });
  typia.assert(member);

  // 2. Create a discussion board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(),
      slug: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(board);

  // 3. Create a post by the member in the board
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
