  TestValidator.equals("created_by matches")(updated.created_by_id)(snapshot.created_by_id);
  TestValidator.equals("updated title matches")(updated.title)(updatedTitle);
  TestValidator.equals("updated body matches")(updated.body)(updatedBody);
  TestValidator.equals("created_at unchanged after update")(updated.created_at)(snapshot.created_at);
