 * 2. Create Member 2 (this user will attempt the unauthorized update)
 * 3. Using Member 1, create a board
 * 4. Using Member 1, create a post on that board
 * 5. Using Member 1, create a post snapshot for that post
 * 6. Attempt to update the snapshot as Member 2 (should fail with authorization error)
 * 7. Attempt to update the snapshot while unauthenticated (should also fail)
 *
 * Expected results:
 * - The system must reject snapshot update attempts from non-creator accounts.
 * - The system must reject snapshot updates by unauthenticated users.
 */
export async function test_api_discussionBoard_test_update_post_snapshot_unauthorized(
  connection: api.IConnection,
) {
  // 1. Create Member 1 (snapshot owner)
  const member1Reg = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
