    post_id: post.id,
    created_by_id: member1.id,
    title: post.title,
    body: post.body,
  } satisfies IDiscussionBoardPostSnapshot.ICreate;
  const snapshot = await api.functional.discussionBoard.postSnapshots.post(connection, { body: snapInput });
  typia.assert(snapshot);

  // 6. Attempt to update snapshot as Member 2 (should fail)
  // Simulate as if authenticated by Member 2 (see note in code)
  await TestValidator.error("Non-owner cannot update post snapshot")(() =>
    api.functional.discussionBoard.postSnapshots.putById(connection, {
      id: snapshot.id,
      body: {
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardPostSnapshot.IUpdate,
    })
