/**
 * Test successful soft-deletion of a post snapshot by its creator or authorized staff.
 *
 * This test validates that a discussion board post snapshot can be successfully soft-deleted
 * by its creator. It covers the complete workflow:
 *   1. Create a discussion board member (for authorship/ownership)
 *   2. Create a discussion board (parent for posts)
 *   3. Create a post in that board authored by the member
 *   4. Create a snapshot for the post
 *   5. Soft-delete the snapshot as the creator
 *   6. Verify the API response returns the snapshot and the deleted id matches
 *
 * Due to limitations in provided API (no list/fetch for snapshots), the test only checks
 * the delete response correctness and ID match.
 */
export async function test_api_discussionBoard_test_delete_post_snapshot_successful(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (author/snapshot creator)
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "P@ssword1234", // Format<"password">
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a discussion board
  const board = await api.functional.discussionBoard.boards.post(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      slug: RandomGenerator.alphabets(10).toLowerCase(),
      description: RandomGenerator.paragraph()(1),
    } satisfies IDiscussionBoardBoard.ICreate,
  });
  typia.assert(board);

  // 3. Create a post in the board authored by the member
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id: board.id,
      author_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Create a snapshot for the post
  const snapshot = await api.functional.discussionBoard.postSnapshots.post(connection, {
    body: {
      post_id: post.id,
      created_by_id: member.id,
      title: post.title,
      body: post.body,
    } satisfies IDiscussionBoardPostSnapshot.ICreate,
  });
