  // 3. Moderator creates a report log for the report
  const reportLog = await api.functional.discussionBoard.reportLogs.post(connection, {
    body: {
      report_id: report.id,
      actor_moderator_id: moderatorMember.id,
      action: "REVIEWED",
      action_comment: "Moderation review comment"
    } satisfies IDiscussionBoardReportLog.ICreate
  });
  typia.assert(reportLog);

  // 4. List logs with filters: report_id, actor_moderator_id, action, date range
  let logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      report_id: report.id,
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      actor_moderator_id: moderatorMember.id,
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log (moderator)")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      action: "REVIEWED",
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log (action)")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      created_from: new Date(Date.now() - 5 * 60 * 1000).toISOString(),
      created_to: new Date(Date.now() + 5 * 60 * 1000).toISOString(),
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.predicate("contains created report log (date range)")(
    logsPage.data.some(x => x.id === reportLog.id)
  );

  // 5. Filters that match nothing
  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      report_id: typia.random<string & tags.Format<"uuid">>(),
      page: 1,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.equals("empty data for unmatched report")(
    logsPage.data
  )([]);

  // 6. Extreme page value (beyond available pages/records)
  logsPage = await api.functional.discussionBoard.reportLogs.patch(connection, {
    body: {
      page: 9999,
      limit: 10
    } satisfies IDiscussionBoardReportLog.IRequest
  });
  typia.assert(logsPage);
  TestValidator.equals("empty data for high page number")(logsPage.data)([]);

  // 7. Bad input and malformed bodies (runtime failures, not TS type errors)
  await TestValidator.error("invalid uuid for report_id")(() =>
    api.functional.discussionBoard.reportLogs.patch(connection, {
      body: {
        report_id: "not-a-uuid"
      } as any
    })
  );

  await TestValidator.error("malformed request body")(async () =>
    api.functional.discussionBoard.reportLogs.patch(connection, {
      body: { page: "str", limit: null } as any
    })
  );

  // 8. Skipped: regular member access denial (no role switch/login API available)
  // await TestValidator.error("regular member forbidden")(...)

  // 9. Pagination object structural check
  TestValidator.predicate("pagination fields present")(
    typeof logsPage.pagination.current === "number" &&
      typeof logsPage.pagination.limit === "number" &&
      typeof logsPage.pagination.records === "number" &&
      typeof logsPage.pagination.pages === "number"
  );
}

