import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardReportCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportCategory";

/**
 * test_list_reports_with_various_filters_and_pagination_as_moderator
 *
 * 다양한 조합의 신고 데이터가 존재할 때, MODERATOR 권한으로 필터별 및 페이지네이션이 올바르게 동작하는지 확인한다.
 *
 * 1. 여러 TEST MEMBER를 생성한다.
 * 2. 여러 가상의 카테고리 UUID 집합을 준비한다.
 * 3. 다양한 멤버·카테고리·타깃 조합으로 신고 여러 건을 등록한다.
 * 4. MODERATOR 권한(가정)에서 다양한 필터/페이지네이션 조합으로 목록/검색 호출 - 결과가 필터와 일치하는지, 메타 정보 일관성, 오프셋 벗어난 페이지 시 빈 결과 등 검증.
 * 5. 권한이 없는 일반회원으로 목록을 호출했을 때 permission error 발생 확인.
 */
export async function test_api_discussionBoard_test_list_reports_with_various_filters_and_pagination_as_moderator(
  connection: api.IConnection,
) {
  // 1. 여러 테스트 멤버 생성
  const memberCount = 4;
  const members = await ArrayUtil.asyncRepeat(memberCount)(async () => {
    const output = await api.functional.discussionBoard.members.post(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        password: "TestPW@1234" as string & tags.Format<"password">,
      },
    });
    typia.assert(output);
    return output;
  });

  // 2. 여러 가상의 신고 카테고리 UUID 설정(등록 API 없음)
  const categoryCount = 3;
  const fakeCategories = ArrayUtil.repeat(categoryCount)(() => typia.random<string & tags.Format<"uuid">>());

  // 3. 신고 다양한 조합으로 대량 생성 (분산)
  // - status: open/resolved/other, 
  // - report_category, reported_by, target_post_id/target_comment_id 조합 다르게
  const statusList = ["open", "resolved", "closed"];
  const reportCount = 15;
  type CreatedReport = {
    report: IDiscussionBoardReport;
    status: string;
    report_category_id: string;
    reporter: typeof members[number];
    target_post_id: string | null;
    target_comment_id: string | null;
    created_at: string;
  };
  const createdReports: CreatedReport[] = [];

  for (let i = 0; i < reportCount; ++i) {
    const status = RandomGenerator.pick(statusList);
    const categoryId = RandomGenerator.pick(fakeCategories);
    const reporter = RandomGenerator.pick(members);
    const isPostTarget = Math.random() < 0.5;
    const target_post_id = isPostTarget ? typia.random<string & tags.Format<"uuid">>() : null;
    const target_comment_id = !isPostTarget ? typia.random<string & tags.Format<"uuid">>() : null;
    // created_at 조작
    const created_at = new Date(Date.now() - typia.random<number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<86400>>() * 1000).toISOString();

    const report = await api.functional.discussionBoard.reports.post(connection, {
      body: {
        reported_by_member_id: reporter.id,
        report_category_id: categoryId,
        target_post_id: target_post_id,
        target_comment_id: target_comment_id,
        description: RandomGenerator.paragraph()(1),
      },
    });
    typia.assert(report);
    // status/created_at 조작(실제 엔드포인트로는 불가지만, 테스트 한계 내에서 만들어둠)
    createdReports.push({
      report,
      status,
      report_category_id: categoryId,
      reporter,
      target_post_id,
      target_comment_id,
      created_at,
    });
  }

  // 4-1. status filter (각 상태별)
  for (const status of statusList) {
    const filtered = createdReports.filter((r) => r.status === status);
    const output = await api.functional.discussionBoard.reports.patch(connection, {
      body: { status },
    });
    typia.assert(output);
    TestValidator.predicate(`filter-status='${status}'`)(
      output.data.every((row) => row.status === status),
    );
    TestValidator.equals(`status-filter matched count`)(output.data.length)(filtered.length);
  }

  // 4-2. 카테고리/신고자 별 필터
  for (const category of fakeCategories) {
    const filtered = createdReports.filter((r) => r.report_category_id === category);
    const output = await api.functional.discussionBoard.reports.patch(connection, {
      body: { report_category_id: category },
    });
    typia.assert(output);
    TestValidator.predicate(`category filter`)(
      output.data.every((row) => row.report_category.id === category),
    );
    TestValidator.equals(`category-filter matched count`)(output.data.length)(filtered.length);
  }
  for (const member of members) {
    const filtered = createdReports.filter((r) => r.reporter.id === member.id);
    const output = await api.functional.discussionBoard.reports.patch(connection, {
      body: { reported_by_member_id: member.id },
    });
    typia.assert(output);
    TestValidator.predicate(`reporter filter`)(
      output.data.every((row) => row.reported_by.id === member.id),
    );
    TestValidator.equals(`reporter-filter matched count`)(output.data.length)(filtered.length);
  }

  // 4-3. 타깃(post/comment별)
  const postTargets = createdReports.filter((r) => r.target_post_id).map((r) => r.target_post_id) as string[];
  if (postTargets.length > 0) {
    const postId = RandomGenerator.pick(postTargets);
    const filtered = createdReports.filter((r) => r.target_post_id === postId);
    const output = await api.functional.discussionBoard.reports.patch(connection, {
      body: { target_post_id: postId },
    });
    typia.assert(output);
    TestValidator.predicate(`target_post_id filter`)(
      output.data.every((row) => row.target_post_id === postId),
    );
    TestValidator.equals(`target_post_id filter count`)(output.data.length)(filtered.length);
  }
  const commentTargets = createdReports.filter((r) => r.target_comment_id).map((r) => r.target_comment_id) as string[];
  if (commentTargets.length > 0) {
    const commentId = RandomGenerator.pick(commentTargets);
    const filtered = createdReports.filter((r) => r.target_comment_id === commentId);
    const output = await api.functional.discussionBoard.reports.patch(connection, {
      body: { target_comment_id: commentId },
    });
    typia.assert(output);
    TestValidator.predicate(`target_comment_id filter`)(
      output.data.every((row) => row.target_comment_id === commentId),
    );
    TestValidator.equals(`target_comment_id filter count`)(output.data.length)(filtered.length);
  }

  // 4-4. created_from/created_to(날짜검색): createdReports에서 임의 시점 기준 필터
  const filterBaseTime = createdReports[Math.floor(reportCount / 2)].created_at;
  {
    const output = await api.functional.discussionBoard.reports.patch(connection, {
      body: { created_from: filterBaseTime },
    });
    typia.assert(output);
    // 전체 created_at >= filterBaseTime이어야 함
    TestValidator.predicate("created_from filter")(
      output.data.every((row) => new Date(row.created_at) >= new Date(filterBaseTime)),
    );
  }
  {
    const output = await api.functional.discussionBoard.reports.patch(connection, {
      body: { created_to: filterBaseTime },
    });
    typia.assert(output);
    // 전체 created_at <= filterBaseTime
    TestValidator.predicate("created_to filter")(
      output.data.every((row) => new Date(row.created_at) <= new Date(filterBaseTime)),
    );
  }

  // 4-5. 페이지네이션: 페이지별 분배, 없는 페이지 요청 시 빈 배열
