  TestValidator.predicate("Soft delete confirmed")(deleteResult.success === true);

  // Step 7: As admin, patch (list) comment threads for the post (should include both threads)
  const adminThreadsPage = await api.functional.discussionBoard.commentThreads.patch(connection, {
    body: {
      post_id: post.id,
    } satisfies IDiscussionBoardCommentThread.IRequest,
  });
