      author_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(post);

  // 3. 루트 댓글 스레드 생성 (해당 포스트 소속, parent_thread_id=null, depth=0)
  const threadCreate = {
    post_id: post.id,
    parent_thread_id: null,
