import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for the discussion board listing endpoint with pagination and search filters.
 *
 * Validates that paginated discussion board lists are correctly returned with and without
 * filters, that pagination and edge-cases are handled as expected, and that input validation
 * properly rejects malformed filter input.
 *
 * Test process:
 * 1. List all boards with no filters—expects valid pagination and non-deleted boards.
 * 2. Search by 'title' using an actual board's title substring. Only matches should be returned.
 * 3. Filter by 'slug' with a real board slug; expects exact slug matches only.
 * 4. Paginate: request a small limit; check page sizes and returned data count.
 * 5. Edge case: request out-of-bounds page (beyond total pages); response should be empty.
 * 6. Send purposely malformed (wrong type) filter input and verify error is thrown.
 */
export async function test_api_discussionBoard_boards_patch(
  connection: api.IConnection,
) {
  // 1. List all boards with default filters (empty body)
  const allBoards = await api.functional.discussionBoard.boards.patch(connection, {
    body: {},
  });
  typia.assert(allBoards);
  TestValidator.predicate("valid pagination")(allBoards.pagination.pages > 0);
  TestValidator.predicate("all boards have required fields")(
    allBoards.data.every(board =>
      !!board.id &&
      !!board.title &&
      !!board.slug &&
      !!board.created_at &&
      !!board.updated_at
    )
  );

  // 2. Title-based search if boards exist
  if (allBoards.data.length > 0) {
    const boardSample = RandomGenerator.pick(allBoards.data);
    const resultByTitle = await api.functional.discussionBoard.boards.patch(connection, {
      body: { title: boardSample.title },
    });
    typia.assert(resultByTitle);
    TestValidator.predicate("title search only matches")(
      resultByTitle.data.every(board => board.title.includes(boardSample.title))
    );
  }

  // 3. Slug-based search (exact match)
  if (allBoards.data.length > 0) {
    const boardSample = RandomGenerator.pick(allBoards.data);
    const resultBySlug = await api.functional.discussionBoard.boards.patch(connection, {
      body: { slug: boardSample.slug },
    });
    typia.assert(resultBySlug);
    TestValidator.predicate("slug filter only matches")(
      resultBySlug.data.every(board => board.slug === boardSample.slug)
    );
  }

  // 4. Pagination: use limit 2 for manageable test counts
  const limit = 2;
  const pagedBoards = await api.functional.discussionBoard.boards.patch(connection, {
    body: { limit },
  });
  typia.assert(pagedBoards);
  TestValidator.equals("paged record count")(pagedBoards.data.length)(Math.min(limit, pagedBoards.pagination.records));
  TestValidator.equals("limit meta value")(pagedBoards.pagination.limit)(limit);

  // 5. Over-sized page: page index > total pages (expect empty)
  const overSizedPage = pagedBoards.pagination.pages + 1;
  const emptyPage = await api.functional.discussionBoard.boards.patch(connection, {
    body: { page: overSizedPage, limit },
  });
  typia.assert(emptyPage);
  TestValidator.equals("out-of-bounds page data count")(emptyPage.data.length)(0);

  // 6. Malformed input: wrong type for 'page' parameter triggers error
  await TestValidator.error("malformed page type")(() =>
    api.functional.discussionBoard.boards.patch(connection, {
      body: { page: "not-a-number" as any },
    })
  );
}

