  // 2. Owner creates a comment edit record
  const editInput = {
    comment_id: typia.random<string & tags.Format<'uuid'>>(),
    editor_id: ownerReg.id,
    edit_summary: 'Typo correction',
    body_after_edit: 'Fixed a minor typo in the comment.'
  } satisfies IDiscussionBoardCommentEdit.ICreate;

  const commentEdit = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: editInput
  });
  typia.assert(commentEdit);

  // 3. Owner fetches the comment edit by ID - should succeed
  const fetchedByOwner = await api.functional.discussionBoard.commentEdits.getById(connection, {
    id: commentEdit.id
  });
  typia.assert(fetchedByOwner);
  TestValidator.equals('owner sees own comment edit')(fetchedByOwner)(commentEdit);

  // 4. Admin fetches the comment edit by ID - should also succeed
  const fetchedByAdmin = await api.functional.discussionBoard.commentEdits.getById(connection, {
    id: commentEdit.id
  });
  typia.assert(fetchedByAdmin);
  TestValidator.equals('admin sees comment edit')(fetchedByAdmin)(commentEdit);

  // 5. Unrelated outsider access/denial not testable (context switch not supported)
  // Documentation: This step intentionally omitted due to lack of authentication/session APIs.

  // 6. Attempting to fetch a non-existent/invalid edit ID - should get 404 error
  await TestValidator.error('404 on invalid edit ID')(async () => {
    await api.functional.discussionBoard.commentEdits.getById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>()
    });
  });

  // 7. Soft delete logic skipped (no delete APIs exposed)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
