import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * E2E test for creating comment edit records in a discussion board.
 *
 * This function tests the creation of new comment edit records (audit log entries) attached to comments. It covers both valid and invalid scenarios, validating business rules (such as permissions and references) and error handling mechanisms.
 *
 * Business context:
 * - Users (members) can edit their own comments, and these edits must be audited/recorded.
 * - Comment edits reference both the edited comment and the user performing the edit. Snapshots of post-edit content are required.
 * - Audit trails must exist for both successful and failed attempts for compliance.
 *
 * Test steps:
 * 1. Register two users (editor A and editor B).
 * 2. Create an initial comment authored by editor A.
 * 3. Simulate a deleted comment (cannot delete via API, so create an extra comment and use its ID for error test).
 * 4. Attempt to create a comment edit with valid references (comment exists, editor is author)—expect success.
 * 5. Attempt to create a comment edit with a non-existent comment ID—expect error.
 * 6. Attempt to create a comment edit for the simulated deleted comment—expect error.
 * 7. Attempt to create a comment edit by unauthorized user (editor B)—expect error.
 * 8. On success, validate that the comment edit record contains a full audit entry (fields populated as expected).
 */
export async function test_api_discussionBoard_test_create_comment_edit_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Register two users (editor A and editor B)
  const userA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(userA);

  const userB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(userB);

  // 2. Create an initial comment authored by userA
  const postId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: postId,
      thread_id: threadId,
      author_id: userA.id,
      body: RandomGenerator.paragraph()(40),
      depth: 0 as number & tags.Type<"int32">,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. Simulate a deleted comment (create a separate one—not actually deleted but will be referenced for error test)
  const deletedComment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: postId,
      thread_id: threadId,
      author_id: userA.id,
      body: RandomGenerator.paragraph()(20),
      depth: 0 as number & tags.Type<"int32">,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(deletedComment);
  // Mark as deleted: as we can't actually delete, just use the ID for error test.

  // 4. Attempt to create a comment edit with valid references—expect success
  const editSummary = "Typo fix: corrected spelling.";
  const newBody = RandomGenerator.content()()();
  const commentEdit = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: {
      comment_id: comment.id,
      editor_id: userA.id,
      edit_summary: editSummary,
      body_after_edit: newBody,
    } satisfies IDiscussionBoardCommentEdit.ICreate,
  });
  typia.assert(commentEdit);
  // 8. Validate that comment edit record contains a full audit entry
  TestValidator.equals("editor_id matches")(commentEdit.editor_id)(userA.id);
  TestValidator.equals("comment_id matches")(commentEdit.comment_id)(comment.id);
  TestValidator.equals("body_after_edit matches")(commentEdit.body_after_edit)(newBody);
  TestValidator.equals("edit_summary matches")(commentEdit.edit_summary)(editSummary);
  TestValidator.predicate("created_at is present and valid ISO8601")(!!commentEdit.created_at && !isNaN(Date.parse(commentEdit.created_at)));

  // 5. Attempt to create a comment edit with a non-existent comment ID—expect error
  await TestValidator.error("fail on non-existent comment")(() =>
    api.functional.discussionBoard.commentEdits.post(connection, {
      body: {
        comment_id: typia.random<string & tags.Format<"uuid">>(), // random (very likely non-existent)
        editor_id: userA.id,
        edit_summary: "Should fail (no such comment)",
        body_after_edit: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardCommentEdit.ICreate,
    }),
  );

  // 6. Attempt to create a comment edit for the simulated deleted comment—expect error
  await TestValidator.error("fail on deleted comment (simulated)")(() =>
    api.functional.discussionBoard.commentEdits.post(connection, {
      body: {
        comment_id: deletedComment.id, // Simulated 'deleted' by separate comment
        editor_id: userA.id,
        edit_summary: "Should fail (deleted comment)",
        body_after_edit: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardCommentEdit.ICreate,
    }),
  );

  // 7. Attempt to create a comment edit by unauthorized user (editor B, not the author)—expect error
  await TestValidator.error("fail when non-author tries to edit")(() =>
    api.functional.discussionBoard.commentEdits.post(connection, {
      body: {
        comment_id: comment.id,
        editor_id: userB.id,
        edit_summary: "Should fail (not the author)",
        body_after_edit: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardCommentEdit.ICreate,
    }),
  );
}

