import type { IDiscussionBoardCommentEdit } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentEdit";

/**
 * Validate deletion (soft/hard) of a comment edit log entry by both its owner and an admin, enforcement of permissions, and error behavior for non-existent/already-deleted records.
 *
 * Test Covers:
 * 1. Provision admin and regular member accounts.
 * 2. Create a comment as the regular member (the edit log will reference this).
 * 3. Create an edit log for the comment as the regular member (owner).
 * 4. Owner deletes their own comment edit log (success expected).
 * 5. Confirm deletion: attempt re-delete -> expect error (404/not found).
 * 6. Create a second edit log for the same comment.
 * 7. Attempt to delete the second log as another regular user (expect permission denied/403).
 * 8. Admin deletes the second edit log (should succeed).
 * 9. Attempt to delete a non-existent (random UUID) log (expect 404 error result).
 *
 * Notes:
 * - As authentication/login flows are not exposed by the API, account-ownership and admin privilege are simulated by controlling which member ID is used for creation vs deletion.
 * - Listing or GET check of deleted logs is not implemented as no such API is included in provided SDK. Validation covers only delete route behavior and error response.
 */
export async function test_api_discussionBoard_test_delete_comment_edit_log_by_admin_and_owner(
  connection: api.IConnection,
) {
  // 1. Provision admin and two regular members
  const admin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: "A_strong_password1!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin);

  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: "User1_password1@",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<'email'>>(),
      display_name: RandomGenerator.name(),
      password: "User2_password1@",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  // 2. Member1 creates a comment
  const comment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      post_id: typia.random<string & tags.Format<'uuid'>>(),
      thread_id: typia.random<string & tags.Format<'uuid'>>(),
      author_id: member1.id,
      body: RandomGenerator.paragraph()(),
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. Member1 creates an edit log for the comment
  const editLog1 = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: {
      comment_id: comment.id,
      editor_id: member1.id,
      edit_summary: "Initial correction",
      body_after_edit: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCommentEdit.ICreate,
  });
  typia.assert(editLog1);

  // 4. Owner (member1) deletes their own edit log (should succeed)
  await api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog1.id });

  // 5. Confirm deletion: attempt re-delete – expect error (404/not found)
  await TestValidator.error("already deleted edit log should fail")(() =>
    api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog1.id }),
  );

  // 6. Create another log for same comment (by member1)
  const editLog2 = await api.functional.discussionBoard.commentEdits.post(connection, {
    body: {
      comment_id: comment.id,
      editor_id: member1.id,
      edit_summary: "Another change",
      body_after_edit: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardCommentEdit.ICreate,
  });
  typia.assert(editLog2);

  // 7. Attempt to delete edit log as another member (member2) – should fail/forbidden
  await TestValidator.error("member without permission cannot delete edit log")(() =>
    api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog2.id }),
  );

  // 8. Admin deletes the edit log (should succeed)
  await api.functional.discussionBoard.commentEdits.eraseById(connection, { id: editLog2.id });

  // 9. Deleting a non-existent log should return error (404)
  await TestValidator.error("deleting non-existent log returns 404")(() =>
    api.functional.discussionBoard.commentEdits.eraseById(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";
import type { PageDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/PageDiscussionBoardNotification";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate retrieval of a paginated, filterable list of notifications for an authenticated member.
 *
 * This test ensures that the /discussionBoard/notifications PATCH endpoint properly lists paginated notification records for the current user with advanced filter options, and strictly does not expose notifications belonging to other users. It also checks pagination metadata integrity and error handling for bad filters and permissions.
 *
 * Steps:
 * 1. Create a discussion board member (user) to act as the authenticated context.
 * 2. Generate several notification records for this user, mixing types, read/unread status, and delivery/creation timestamps.
 * 3. Create at least one notification for a different recipient to confirm isolation.
 * 4. Attempt to list with various filter sets:
 *    - No filters: should receive all notifications for the test user only
 *    - Type filter: should only return notifications matching that type
 *    - Read/unread filter: filter by whether notifications have read_at set
 *    - Delivery window: filter by delivered_after/delivered_before
 *    - Pagination controls: request specific pages/limits, check correctness
 * 5. Verify result data arrays contain only notifications belonging to the test user, filters are respected, and pagination metadata matches result size.
 * 6. Validate that malformed filter input (e.g., negative page, invalid dates) returns proper error.
 * 7. (If possible) As a non-admin user, attempt to query another member's notifications by setting recipient_member_id; should be denied or return empty result.
 */
export async function test_api_discussionBoard_test_list_notifications_for_authenticated_user_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a member (user)
  const registration = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12),
  } satisfies IDiscussionBoardMember.ICreate;
  const user = await api.functional.discussionBoard.members.post(connection, { body: registration });
  typia.assert(user);

  // 2. Generate notifications for this user
  const notificationTypes = ["mention","reply","like","system_announcement"];
  const now = new Date();
  const notificationData = [
    {
      recipient_member_id: user.id,
      type: notificationTypes[0],
      delivered_at: new Date(now.getTime() - 60 * 1000 * 10).toISOString(), // 10 min ago
    },
    {
      recipient_member_id: user.id,
      type: notificationTypes[1],
      delivered_at: new Date(now.getTime() - 60 * 1000 * 5).toISOString(), // 5 min ago
      read_at: new Date(now.getTime() - 60 * 1000 * 3).toISOString(), // Read 3 min ago
    },
    {
      recipient_member_id: user.id,
      type: notificationTypes[2],
      delivered_at: now.toISOString(),
    },
    {
      recipient_member_id: user.id,
      type: notificationTypes[3],
      delivered_at: now.toISOString(),
    },
  ].map(n => ({
    ...n,
    trigger_actor_id: null,
    target_post_id: null,
    target_comment_id: null,
    target_report_id: null,
    target_section_id: null,
  })) as DiscussionBoardNotification.ICreate[];
  const createdNotifications = [] as DiscussionBoardNotification[];
  for (const data of notificationData) {
    const notif = await api.functional.discussionBoard.notifications.post(connection, { body: data });
    typia.assert(notif);
    createdNotifications.push(notif);
  }

  // 3. Generate notification for another (random) user
  const otherUser = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(otherUser);
  await api.functional.discussionBoard.notifications.post(connection, {
    body: {
      recipient_member_id: otherUser.id,
      type: "mention",
      delivered_at: now.toISOString(),
      trigger_actor_id: null,
      target_post_id: null,
      target_comment_id: null,
      target_report_id: null,
      target_section_id: null,
    } satisfies DiscussionBoardNotification.ICreate,
  });

  // 4a. No filters: should list only this user's notifications
  let result = await api.functional.discussionBoard.notifications.patch(connection, { body: {} });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
  }
  TestValidator.predicate("pagination length matches")(result.data.length <= result.pagination.limit);

  // 4b. Type filter
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { type: notificationTypes[1] } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("type matches")(notif.type)(notificationTypes[1]);
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
  }

  // 4c. Read/unread filter (read)
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { read: true } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.predicate("read_at set")(!!notif.read_at);
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
  }

  // 4d. Read/unread filter (unread)
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { read: false } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
    TestValidator.predicate("read_at null")(notif.read_at == null);
  }

  // 4e. Delivery date window filter
  const deliveredAfter = new Date(now.getTime() - 60 * 1000 * 6).toISOString();
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { delivered_after: deliveredAfter } });
  typia.assert(result);
  for (const notif of result.data) {
    TestValidator.equals("recipient matches user")(notif.recipient_member_id)(user.id);
    TestValidator.predicate("delivered_after respected")(notif.delivered_at >= deliveredAfter);
  }

  // 4f. Pagination params
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { page: 0, limit: 2 } });
  typia.assert(result);
  TestValidator.equals("limit respected")(result.data.length)(Math.min(result.pagination.limit, createdNotifications.length));
  TestValidator.equals("page index")(result.pagination.current)(0);

  // 5. Malformed filter error (negative page)
  await TestValidator.error("negative page should fail")(async () => {
    await api.functional.discussionBoard.notifications.patch(connection, { body: { page: -1 } });
  });

  // 6. Attempt to retrieve another user's notifications as our test user
  result = await api.functional.discussionBoard.notifications.patch(connection, { body: { recipient_member_id: otherUser.id } });
  typia.assert(result);
  // Should not leak others' data (result set should be empty or access denied)
  TestValidator.equals("other user results empty")(result.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";

/**
 * Test retrieving full details of a specific notification by its ID as the owning user.
 *
 * Validates that a user can only see their own notifications with full field visibility,
 * and that access control is enforced for non-existent or unauthorized IDs.
 *
 * Workflow:
 * 1. Register a discussion board member.
 * 2. Create a notification assigned to this member.
 * 3. Fetch the notification as the owner and validate all relevant fields.
 * 4. Attempt to fetch a notification using a random (non-existent) ID and confirm error is raised.
 */
export async function test_api_discussionBoard_test_get_notification_detail_for_owner_user(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (user registration)
  const userInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.alphabets(8),
    password: RandomGenerator.alphabets(12),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: userInput,
  });
  typia.assert(member);

  // 2. Create a notification for this member
  const notifInput = {
    recipient_member_id: member.id,
    type: "mention",
    delivered_at: new Date().toISOString(),
    trigger_actor_id: null,
    target_post_id: null,
    target_comment_id: null,
    target_report_id: null,
    target_section_id: null,
  } satisfies DiscussionBoardNotification.ICreate;
  const notification = await api.functional.discussionBoard.notifications.post(connection, {
    body: notifInput,
  });
  typia.assert(notification);

  // 3. Fetch the notification by its ID as the owning user
  const detail = await api.functional.discussionBoard.notifications.getById(
    connection,
    { id: notification.id },
  );
  typia.assert(detail);
  TestValidator.equals("id")(detail.id)(notification.id);
  TestValidator.equals("recipient_member_id")(detail.recipient_member_id)(member.id);
  TestValidator.equals("type")(detail.type)(notifInput.type);
  TestValidator.equals("delivered_at")(detail.delivered_at)(notifInput.delivered_at);
  // Optionally check other fields for null if all were set to null
  TestValidator.equals("trigger_actor_id")(detail.trigger_actor_id)(null);
  TestValidator.equals("target_post_id")(detail.target_post_id)(null);
  TestValidator.equals("target_comment_id")(detail.target_comment_id)(null);
  TestValidator.equals("target_report_id")(detail.target_report_id)(null);
  TestValidator.equals("target_section_id")(detail.target_section_id)(null);

  // 4. Attempt to fetch a non-existent notification ID (negative test)
  await TestValidator.error("not found for non-existent notification")(() =>
    api.functional.discussionBoard.notifications.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { DiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/DiscussionBoardNotification";

/**
 * 비수신자(다른 회원)가 알림 상세를 조회하려고 시도할 때 차단되는지 검증한다.
 *
 * - 회원 A(알림 수신자)와 회원 B(권한 없는 사용자를) 각각 계정 생성
 * - 회원 A에게 알림을 생성
 * - B의 사용자 인증으로 알림 상세조회 시도
 *
 * ## 기대 결과
 * - 본인(A)이 아닌 B가 접근하면 서버는 반드시 권한 오류(403 등)를 반환해야 한다.
 * - 상세 데이터 노출 없이, 명확한 접근 거부만 발생해야 한다.
 */
export async function test_api_discussionBoard_test_get_notification_detail_by_non_owner_forbidden(
  connection: api.IConnection,
) {
  // 1. 회원 A(수신자) 계정 생성
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Password123!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberA);

  // 2. 회원 B(비수신자) 계정 생성
  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(12),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "Password123!",
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. 회원 A에게 알림 생성 (트리거=B)
  const notification = await api.functional.discussionBoard.notifications.post(connection, {
    body: {
      recipient_member_id: memberA.id,
      trigger_actor_id: memberB.id,
      type: "mention",
      delivered_at: new Date().toISOString(),
    } satisfies DiscussionBoardNotification.ICreate,
  });
  typia.assert(notification);

  // 4. B로 인증 토큰 전환(테스트환경: 임시 헤더로 신분 시뮬레이션)
  const bConnection: api.IConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      "x-mock-user-id": memberB.id,
    },
  };

  // 5. B가 A의 알림 상세에 접근 시도 → 반드시 실패해야 함
  await TestValidator.error("비수신자 접근 차단")(() =>
    api.functional.discussionBoard.notifications.getById(bConnection, { id: notification.id })
  );
}

