  typia.assert(admin);

  // (관리자 인증 상태, 즉 admin_member가 인증된 상황이라고 가정)

  // 3. 존재하지 않는 게시글 ID로 notification 생성 요청 (target_post_id에 랜덤 UUID)
  const bogus_post_id = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 게시글을 알림 타깃으로 지정 시 에러 반환")(() =>
    api.functional.discussionBoard.notifications.post(connection, {
      body: {
        recipient_member_id: recipient.id,
