/**
 * 회원이 본인에게 온 알림을 소프트 삭제(출금/철회)하는 정상 시나리오를 검증합니다.
 *
 * - 알림 수신자인 회원이 삭제 요청을 할 수 있음
 * - 삭제/철회된 알림은 삭제 직후 반환값으로 확인 가능
 * - 삭제 엔트리의 id와 recipient 필드가 입력값과 일치하는지 검증
 * - fetch API 부재로 실제 목록 제외 여부는 생략 (fetch API 도입 시 추가 검증 필요)
 *
 * 단계:
 * 1. 회원 생성 (알림 수신자 역할)
 * 2. 해당 회원에게 알림 생성
 * 3. 수신자가 알림을 삭제(소프트 삭제/철회)
 * 4. 삭제 결과 엔트리의 id/수신자가 입력값과 동일한지 확인
 */
export async function test_api_discussionBoard_test_delete_notification_by_owner_user(
  connection: api.IConnection,
) {
  // 1. 회원 생성 (알림 수신자)
  const memberInput = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: memberInput,
  });
  typia.assert(member);

  // 2. 알림 생성 (recipient: 위에서 만든 회원)
  const notificationInput = {
    recipient_member_id: member.id,
    type: "mention",
    delivered_at: new Date().toISOString(),
  } satisfies DiscussionBoardNotification.ICreate;
  const notification = await api.functional.discussionBoard.notifications.post(connection, {
    body: notificationInput,
  });
  typia.assert(notification);
  TestValidator.equals("수신자 일치")(notification.recipient_member_id)(member.id);

  // 3. 수신자가 알림 소프트 삭제
  const deleted = await api.functional.discussionBoard.notifications.eraseById(connection, {
    id: notification.id,
  });
  typia.assert(deleted);
  TestValidator.equals("삭제한 알림 ID 일치")(deleted.id)(notification.id);
  TestValidator.equals("삭제 알림의 수신자 일치")(deleted.recipient_member_id)(member.id);

  // 4. fetch API 부재로 목록 비노출 여부 검증은 생략
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
