      limit: 10,
    },
  });
  typia.assert(by_type);
  TestValidator.predicate('All have action_type warn')(
    by_type.data.every(x => x.action_type === 'warn')
  );

  // 6. Search by date range (created_at_from/to from known test actions)
  const from = created_actions[1].created_at;
  const to = created_actions[3].created_at;
  const by_date = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      created_at_from: from,
      created_at_to: to,
      limit: 10,
    },
  });
  typia.assert(by_date);
  TestValidator.predicate('All in date range')(
    by_date.data.every(x => x.created_at >= from && x.created_at <= to)
  );

  // 7. Multiple filters (intersection)
  const intersection = await api.functional.discussionBoard.moderationActions.patch(connection, {
    body: {
      moderator_id,
      action_type: 'suspend',
      affected_member_id: affected_member_ids[0],
      limit: 10,
    },
  });
  typia.assert(intersection);
  TestValidator.predicate('Intersection matches')(
    intersection.data.every(x =>
      x.moderator_id === moderator_id &&
      x.action_type === 'suspend' &&
      x.affected_member_id === affected_member_ids[0]
    )
  );

  // 8. Malformed filter values
  await TestValidator.error('Invalid UUID for moderator_id')(
    async () => {
      await api.functional.discussionBoard.moderationActions.patch(connection, {
        body: {
          moderator_id: 'not-a-uuid',
        },
      });
    }
  );
  await TestValidator.error('Unknown action_type value')(
    async () => {
      await api.functional.discussionBoard.moderationActions.patch(connection, {
        body: {
          action_type: 'not-a-real-type',
        },
      });
    }
  );

  // 9. Unauthorized access: not testable unless E2E infra supplies unauthenticated connection.
}

