/**
 * Test deleting a post reaction (soft delete) as both the original creator and as a moderator (business simulated).
 *
 * This test exercises the post reaction deletion (soft delete), ensuring:
 * 1. A member can delete their own post reaction, and double deletion is handled properly (idempotence/error).
 * 2. A moderator (simulated, since no real role elevation API) can delete another user's reaction.
 * 3. Unauthorized users cannot delete others' reactions.
 * 4. Deleting nonexistent or already deleted reactions returns errors.
 *
 * Note: Since the SDK does not expose role elevation, listing, or recovery APIs,
 * assertions for visibility/auditing are limited to delete operations and error responses.
 */
export async function test_api_discussionBoard_test_delete_post_reaction_with_authorization_and_state_checks(
  connection: api.IConnection,
) {
  // 1. Create two members: reaction creator and 'moderator' for scenario simulation
  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "User1Pwd!234" as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member1);

  const moderator = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "ModPwd!1234" as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(moderator);

  // 2. Create a board/post as the reacting user (board_id is generated randomly as there is no board create API)
  const board_id = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id,
      author_id: member1.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a post reaction as the reacting user
  const reaction = await api.functional.discussionBoard.postReactions.post(connection, {
    body: {
      discussionboard_member_id: member1.id,
      discussionboard_post_id: post.id,
      reaction_type: "like",
    } satisfies IDiscussionBoardPostReaction.ICreate,
  });
  typia.assert(reaction);

  // 4. Member deletes their own reaction
  await api.functional.discussionBoard.postReactions.eraseById(connection, { id: reaction.id });

  // 5. Double deletion should error (idempotence/error check)
  await TestValidator.error("double delete should error")(
    () => api.functional.discussionBoard.postReactions.eraseById(connection, { id: reaction.id }),
  );

  // 6. Nonexistent reaction deletion should error
  await TestValidator.error("non-existent reaction error")(
    () => api.functional.discussionBoard.postReactions.eraseById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 7. Simulate moderator deleting someone else's reaction
  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "User2Pwd!456" as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member2);

  const post2 = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      board_id,
      author_id: member2.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post2);

  const reaction2 = await api.functional.discussionBoard.postReactions.post(connection, {
    body: {
      discussionboard_member_id: member2.id,
      discussionboard_post_id: post2.id,
      reaction_type: "like",
    } satisfies IDiscussionBoardPostReaction.ICreate,
  });
  typia.assert(reaction2);

  // 'Moderator' deletes member2's reaction
  await api.functional.discussionBoard.postReactions.eraseById(connection, { id: reaction2.id });

  // 8. Attempt unauthorized deletion: member1 tries to delete member2's already deleted reaction (should error)
  await TestValidator.error("unauthorized deletion error")(
    () => api.functional.discussionBoard.postReactions.eraseById(connection, { id: reaction2.id }),
  );

  // NOTE: No list/query API is available to check hiding of deleted reactions,
  // nor an admin/audit endpoint for soft-deleted records, so those checks are omitted.
}

