/**
 * 검증 오류 케이스: 필수 항목 누락 또는 schema 위반 input 값에 대해 시스템이 validation error를 올바르게 반환하고 엔트리를 생성하지 않아야 함을 검증
 *
 * 비즈니스 목적:
 * - 시스템 설정(configuration) 입력 시 key, value 등 필수값 누락 또는 input 이상 시 명확한 오류를 반환하고, 실제 entry가 생성되지 않는지 보장
 * - 해당 정책이 audit/컴플라이언스 요구조건을 충족하는지 확인
 *
 * 테스트 시나리오:
 * 1. 관리자 멤버 생성 (의존성)
 * 2. key 필수값 누락 케이스: { value } 만 넣어서 생성 (실패해야 함)
 * 3. key가 빈 문자열인 케이스: { key: "", value } (정책상 금지인 경우 실패해야 함)
 * 4. value 필수값 누락 케이스: { key } 만 넣어서 생성 (실패해야 함)
 * 5. value가 빈 문자열인 케이스: { key, value: "" } (정책상 금지라면 실패, 허용된다면 test 수정)
 *
 * 유의사항:
 * - 타입 시스템에서 검출되는 컴파일 오류(즉, TS에서 아예 불가능)는 테스트하지 않음
 * - 실제 런타임에서 입력값 검증 로직이 정상 동작하는지 위주로 검증
 * - 각 오류 케이스에 대해 TestValidator.error()를 사용하여 명확히 에러를 기대함을 표현
 * - 비즈니스 정책에 따라 빈 문자열 허용 여부 조정 가능
 */
export async function test_api_discussionBoard_test_create_configuration_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. 관리자 멤버 생성(권한 선행조건)
  const adminInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: "admin-secure-pass!1",
  };
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: adminInput,
  });
  typia.assert(adminMember);

  // 2. key 누락 (value만 전달)
  await TestValidator.error("key 필수값 누락시 생성 거부")(
    async () => {
      return api.functional.discussionBoard.configurations.post(connection, {
        body: {
          value: "arbitrary-value",
        } as any,
      });
    }
  );

  // 3. key가 빈 문자열인 경우
  await TestValidator.error("key가 빈 문자열이면 생성 거부")(
    async () => {
      return api.functional.discussionBoard.configurations.post(connection, {
        body: {
          key: "",
          value: "meaningful-value",
        },
      });
    }
  );

  // 4. value 누락 (key만 전달)
  await TestValidator.error("value 필수값 누락시 생성 거부")(
    async () => {
      return api.functional.discussionBoard.configurations.post(connection, {
        body: {
          key: "config-key-without-value",
        } as any,
      });
    }
  );

  // 5. value가 빈 문자열인 경우 (정책 미정일 경우 실패 처리, 허용된다면 테스트에서 제외)
  await TestValidator.error("value가 빈 문자열이면 생성 거부")(
    async () => {
      return api.functional.discussionBoard.configurations.post(connection, {
        body: {
          key: "config-key-empty-value",
          value: "",
        },
      });
    }
  );
}

