/**
 * Test uniqueness constraint on configuration key during update.
 *
 * This test attempts to verify that the API enforces uniqueness of configuration keys on update. However, according to the provided DTOs and endpoint specifications, the `PUT /discussionBoard/configurations/{id}` endpoint does NOT allow updating the `key` field—only `value` and (optionally) `description` are editable. Therefore, this test can only confirm that updating value/description does NOT trigger a key uniqueness violation, but CANNOT actually provoke a uniqueness conflict on `key`.
 *
 * Steps:
 * 1. Register an admin member — required for configuration update permissions.
 * 2. Create two configurations (`confA` and `confB`) with different keys.
 * 3. Attempt to update `confB`'s value/description only (since 'key' cannot be updated).
 *     - This should always succeed, since unique key constraint only applies on creation, not update.
 * 4. Document that a uniqueness conflict on key cannot be tested via update per current API contracts.
 */
export async function test_api_discussionBoard_test_update_configuration_with_duplicate_key(
  connection: api.IConnection,
) {
  // 1. Register admin user (no login/auth API, so just create member)
  const admin: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: "A!a12345" as string & tags.Format<"password">,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(admin);

  // 2. Create two configurations with different keys
  const keyA = "max_post_length_" + RandomGenerator.alphabets(5);
  const keyB = "min_post_length_" + RandomGenerator.alphabets(5);

  const confA: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.post(connection, {
    body: {
      key: keyA,
      value: "10000",
      description: "Config A",
    } satisfies IDiscussionBoardConfiguration.ICreate,
  });
  typia.assert(confA);

  const confB: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.post(connection, {
    body: {
      key: keyB,
      value: "1000",
      description: "Config B",
    } satisfies IDiscussionBoardConfiguration.ICreate,
  });
  typia.assert(confB);

  // 3. Attempt to update confB's value/description only (key is NOT updatable)
  const updatedConfB: IDiscussionBoardConfiguration = await api.functional.discussionBoard.configurations.putById(connection, {
    id: confB.id,
    body: {
      value: "2222",
      description: "Updated value only; key cannot be changed via update",
