import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentReaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageDiscussionBoardCommentReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardCommentReaction";

/**
 * E2E test for searching and paginating comment reaction records using complex filters, including paging and soft-delete visibility.
 *
 * This test ensures comment reactions can be searched with multifaceted filters and pagination controls, and that business rules
 * regarding unique member-comment-reaction type combinations, and soft-deletion visibility, are enforced.
 *
 * Steps:
 * 1. Create multiple discussion board members for later reaction associations.
 * 2. Create multiple comments (across different posts/threads) that will serve as reaction targets.
 * 3. For each member/comment/reaction_type combination, create a reaction record ("like" and "dislike").
 * 4. For each filter type, search via PATCH /discussionBoard/commentReactions and assert the response matches expectations
 *    (by comment, by member, by reaction_type, by timestamp, by paging constraints).
 * 5. Confirm that only undeleted (active) reactions are surfaced in the results (deleted_at is null).
 * 6. Test that pagination limits are respected on result data.
 *    Also, verify combined filter scenarios and zero-result edge cases.
 *    As API for soft-delete is unavailable, explain this by comment and focus on validation of strict active-only response.
 */
export async function test_api_discussionBoard_test_list_comment_reactions_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Prepare members for test
  const memberInputs = ArrayUtil.repeat(3)(() => ({
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(15),
  }) satisfies IDiscussionBoardMember.ICreate);
  const members = await ArrayUtil.asyncMap(memberInputs)(async (input) => {
    const member = await api.functional.discussionBoard.members.post(connection, {
      body: input,
    });
    typia.assert(member);
    return member;
  });

  // 2. Prepare comments. For this test, assign comments to different posts and threads.
  const commentInputs = ArrayUtil.repeat(2)(() => {
    const author = RandomGenerator.pick(members.map((m) => m.id));
    return {
      post_id: typia.random<string & tags.Format<"uuid">>(),
      thread_id: typia.random<string & tags.Format<"uuid">>(),
      author_id: author,
      body: RandomGenerator.content()()(),
      depth: 0,
    } satisfies IDiscussionBoardComment.ICreate;
  });
  const comments = await ArrayUtil.asyncMap(commentInputs)(async (input) => {
    const comment = await api.functional.discussionBoard.comments.post(connection, {
      body: input,
    });
    typia.assert(comment);
    return comment;
  });

  // 3. Generate reactions for every member-comment-reaction type tuple
  const reactionTypes = ["like", "dislike"];
  const createdReactions: IDiscussionBoardCommentReaction[] = [];
  for (const member of members) {
    for (const comment of comments) {
      for (const reaction_type of reactionTypes) {
        const reaction = await api.functional.discussionBoard.commentReactions.post(connection, {
          body: {
            discussionboard_member_id: member.id,
            discussionboard_comment_id: comment.id,
            reaction_type: reaction_type,
          } satisfies IDiscussionBoardCommentReaction.ICreate,
        });
        typia.assert(reaction);
        createdReactions.push(reaction);
      }
    }
  }

  // 4. Filtering tests
  // a. By comment ID
  for (const comment of comments) {
    const res = await api.functional.discussionBoard.commentReactions.patch(connection, {
      body: {
        discussionboard_comment_id: comment.id,
        paging: { page: 1, limit: 20 },
      } satisfies IDiscussionBoardCommentReaction.IRequest,
    });
    typia.assert(res);
    TestValidator.predicate("comment filter: all reactions match comment")(
      res.data.every((r) => r.discussionboard_comment_id === comment.id),
    );
    TestValidator.equals("comment filter: expected count")(res.data.length)(members.length * reactionTypes.length);
  }

  // b. By member ID
  for (const member of members) {
    const res = await api.functional.discussionBoard.commentReactions.patch(connection, {
      body: {
        discussionboard_member_id: member.id,
        paging: { page: 1, limit: 20 },
      } satisfies IDiscussionBoardCommentReaction.IRequest,
    });
    typia.assert(res);
    TestValidator.predicate("member filter: all reactions match member")(
      res.data.every((r) => r.discussionboard_member_id === member.id),
    );
    TestValidator.equals("member filter: expected count")(res.data.length)(comments.length * reactionTypes.length);
  }

  // c. By reaction_type
  for (const type of reactionTypes) {
    const res = await api.functional.discussionBoard.commentReactions.patch(connection, {
      body: {
        reaction_type: type,
        paging: { page: 1, limit: 100 },
      } satisfies IDiscussionBoardCommentReaction.IRequest,
    });
    typia.assert(res);
    TestValidator.predicate("reaction_type filter: all correct type")(
      res.data.every((r) => r.reaction_type === type),
    );
    TestValidator.equals("reaction_type filter: expected count")(res.data.length)(members.length * comments.length);
  }

  // d. By created_after / created_before
  // For edge, use a real boundary value from reaction timestamps
  const allCreatedAt = createdReactions.map((x) => x.created_at).sort();
  const afterVal = allCreatedAt[0];
  const beforeVal = allCreatedAt[allCreatedAt.length - 1];
  const afterRes = await api.functional.discussionBoard.commentReactions.patch(connection, {
    body: {
      created_after: afterVal,
      paging: { page: 1, limit: 100 },
    },
  });
  typia.assert(afterRes);
  TestValidator.predicate("created_after: all reactions on/after boundary")(
    afterRes.data.every((r) => r.created_at >= afterVal),
  );

  const beforeRes = await api.functional.discussionBoard.commentReactions.patch(connection, {
    body: {
      created_before: beforeVal,
      paging: { page: 1, limit: 100 },
    },
  });
  typia.assert(beforeRes);
  TestValidator.predicate("created_before: all reactions strictly before boundary")(
    beforeRes.data.every((r) => r.created_at < beforeVal),
  );

  // e. Combined filter (member + type)
  for (const member of members) {
    for (const type of reactionTypes) {
      const res = await api.functional.discussionBoard.commentReactions.patch(connection, {
        body: {
          discussionboard_member_id: member.id,
          reaction_type: type,
          paging: { page: 1, limit: 10 },
        },
      });
      typia.assert(res);
      TestValidator.predicate("combined filter - type/member: correct member/type only")(
        res.data.every((r) => r.discussionboard_member_id === member.id && r.reaction_type === type),
      );
      TestValidator.equals("combined filter - type/member: expected count")(res.data.length)(comments.length);
    }
  }

  // f. Edge: zero results - filter by invalid comment ID
  const noMatchRes = await api.functional.discussionBoard.commentReactions.patch(connection, {
    body: { discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(), paging: { page: 1, limit: 5 } },
  });
  typia.assert(noMatchRes);
  TestValidator.equals("zero result filter: empty array")(noMatchRes.data.length)(0);

  // 5. Pagination control test: limit = 2
  const pagedRes = await api.functional.discussionBoard.commentReactions.patch(connection, {
    body: { paging: { page: 1, limit: 2 } },
  });
  typia.assert(pagedRes);
  TestValidator.equals("pagination: limit 2 only")(pagedRes.data.length)(2);
  TestValidator.equals("pagination meta: limit")(pagedRes.pagination.limit)(2);
  TestValidator.equals("pagination meta: current page")(pagedRes.pagination.current)(1);

  // 6. Soft-deletion exclusion: cannot delete, but verify no deleted_at fields are present
  const allRes = await api.functional.discussionBoard.commentReactions.patch(connection, {
    body: { paging: { page: 1, limit: 100 } },
  });
  typia.assert(allRes);
  TestValidator.predicate("all reactions are active (deleted_at null)")(
    allRes.data.every((r) => r.deleted_at === null || r.deleted_at === undefined),
  );

  // 7. Consistency check: number of returned active reactions matches creation count
  TestValidator.equals("created reactions vs. active")(allRes.data.length)(createdReactions.length);
}

