  const pageA_emailDisabled = await api.functional.discussionBoard.notificationPreferences.patch(connection, {
    body: {
      member_id: memberA.id,
      enable_email: false,
      enable_web_push: null,
      enable_system_announcements: null,
      page: null,
    },
  });
  typia.assert(pageA_emailDisabled);
  TestValidator.equals("should return empty array for enable_email=false")(pageA_emailDisabled.data.length)(0);

  // 5. Negative: create another member with only email disabled
  const memberBInput = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
