  const prefsB = await api.functional.discussionBoard.notificationPreferences.post(connection, {
    body: {
      member_id: memberB.id,
      enable_email: false,
      enable_web_push: true,
      enable_system_announcements: true,
    },
  });
  typia.assert(prefsB);

  // Fetch with email enabled - memberB should not appear
  const pageB_emailEnabled = await api.functional.discussionBoard.notificationPreferences.patch(connection, {
    body: {
      member_id: memberB.id,
      enable_email: true,
      enable_web_push: null,
      enable_system_announcements: null,
