 *
 * Test steps:
 * 1. Create two distinct member accounts.
 * 2. Assign the admin role to the first member (elevated privileges).
 * 3. For each member, create a notification preference record with intentionally different settings.
 * 4. As the admin, request a paged and sorted list (simulate updated_at descending).
 * 5. Assert that the response contains both preference records in the correct order, and pagination information is accurate.
 */
export async function test_api_discussionBoard_notificationPreferences_test_list_notification_preferences_pagination_and_sorting_as_admin(
  connection: api.IConnection,
) {
  // 1. Create two distinct member accounts
  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      display_name: RandomGenerator.name(),
      password: RandomGenerator.alphaNumeric(12) as string & tags.Format<"password">,
    },
