  const createMemberInput: IDiscussionBoardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    password: RandomGenerator.alphaNumeric(12),
  };
  const member = await api.functional.discussionBoard.members.post(connection, { body: createMemberInput });
  typia.assert(member);

  // 2. 해당 멤버로 로그인(로그인 API가 없으므로, 가입 시 바로 인증된 상태로 간주)
  // (connection은 이미 인증 상태로 간주하고 진행)

  // 3. 알림 환경설정 신규 생성
  const preferenceInput = {
    member_id: member.id,
    enable_email: true,
    enable_web_push: false,
    enable_system_announcements: true,
  } satisfies DiscussionBoardNotificationPreferences.ICreate;
  const preference = await api.functional.discussionBoard.notificationPreferences.post(connection, { body: preferenceInput });
  typia.assert(preference);

  // 4. ID로 환경설정 직접 조회
  const fetched = await api.functional.discussionBoard.notificationPreferences.getById(connection, { id: preference.id });
  typia.assert(fetched);

  // 5. 입력값과 DB 결과값 필드 일치 여부 검증
  TestValidator.equals("member id matches")(fetched.member_id)(member.id);
  TestValidator.equals("enable_email matches")(fetched.enable_email)(preferenceInput.enable_email);
  TestValidator.equals("enable_web_push matches")(fetched.enable_web_push)(preferenceInput.enable_web_push);
  TestValidator.equals("enable_system_announcements matches")(fetched.enable_system_announcements)(preferenceInput.enable_system_announcements);

  // created_at, updated_at 형식 검증
  TestValidator.predicate("created_at is ISO8601 date-time")(!!Date.parse(fetched.created_at));
  TestValidator.predicate("updated_at is ISO8601 date-time")(!!Date.parse(fetched.updated_at));

  // 6. 존재하지 않는 환경설정 ID로 조회 시 오류 검증
  await TestValidator.error("존재하지 않는 환경설정 ID 조회시 오류")(
    async () => {
      await api.functional.discussionBoard.notificationPreferences.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(), // 실존하지 않는 ID
      });
    },
  );
}

