/**
 * Validate paginated and filtered retrieval of content policies with search, filter, and pagination parameters.
 *
 * This test ensures that listing/search API returns correct, filtered results for different combinations of policy attributes and pagination arguments.
 *
 * Steps:
 * 1. Create at least 5 policies:
 *    - Varying activation status (is_active true/false).
 *    - Different effective_from and effective_to (some active, some expired, some future).
 *    - Diverse code/title/description substrings (some overlapping for search test).
 * 2. Test: Retrieve all policies unfiltered (should return all created, check count matches).
 * 3. Test: Search by substring in code (should return only matching policies, check data array and matching within code).
 * 4. Test: Filter by activation status is_active=true (should only return active policies).
 * 5. Test: Filter by activation status is_active=false (should only return inactive policies).
 * 6. Test: Filter by date range (effective_from, effective_to) for current/future/past policies.
 * 7. Test: Pagination - limit to 2 per page, navigate pages, check data, total count, correctness.
 * 8. [Optional] Test unauthorized access and restricted policy filtering, if API applies (not required if endpoint is open).
 * All results should match expectations for number, order, and policy details as per filters.
 */
export async function test_api_discussionBoard_contentPolicies_test_list_content_policies_with_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. Create seed policy dataset with diverse attribute combinations
  //    - 3 active (current), 1 future (effective_from in the future), 1 inactive (expired, is_active=false)
  const baseTime = new Date();
  // Create policies array for test coverage (use code substring variations etc)
  const POLICIES = [
    { // Active, code includes 'GENERAL'
      code: "GENERAL_POLICY",
      title: "General Policy",
      description: "Covers general conduct for all members.",
      effective_from: new Date(new Date(baseTime).setDate(baseTime.getDate() - 60)).toISOString(),
      effective_to: null,
      is_active: true,
    },
    { // Active, code includes 'HATE'
      code: "HATE_SPEECH_2024",
      title: "Hate Speech Policy",
      description: "Regulates hate speech in public and private discussions.",
      effective_from: new Date(new Date(baseTime).setDate(baseTime.getDate() - 30)).toISOString(),
      effective_to: null,
      is_active: true,
    },
    { // Active, code includes 'TEMP'
      code: "TEMP_POLICY_A",
      title: "Temporary Rule A",
      description: "Covers temporary event moderation.",
      effective_from: new Date(new Date(baseTime).setDate(baseTime.getDate() - 20)).toISOString(),
      effective_to: null,
      is_active: true,
    },
    { // Inactive (expired), code includes 'EXPIRED'
      code: "EXPIRED_POLICY_B",
      title: "Old Rule B",
      description: "This was an old, now expired policy.",
      effective_from: new Date(new Date(baseTime).setFullYear(baseTime.getFullYear() - 1)).toISOString(),
      effective_to: new Date(new Date(baseTime).setDate(baseTime.getDate() - 90)).toISOString(),
      is_active: false,
    },
    { // Future policy, code includes 'FUTURE'
      code: "FUTURE_RULE_C",
      title: "Planned Rule C",
      description: "Rule to take effect next month.",
      effective_from: new Date(new Date(baseTime).setDate(baseTime.getDate() + 30)).toISOString(),
      effective_to: null,
      is_active: true,
    },
  ];
  // Actually create these policies
  const createdPolicies = [];
  for (const item of POLICIES) {
    const record = await api.functional.discussionBoard.contentPolicies.post(connection, {
      body: {
        code: item.code,
        title: item.title,
        description: item.description,
        effective_from: item.effective_from as string & tags.Format<"date-time">,
        effective_to: item.effective_to as (string & tags.Format<"date-time">) | null,
        is_active: item.is_active,
      }
    });
    typia.assert(record);
    createdPolicies.push(record);
  }

  // 2. Retrieve all policies unfiltered
  let res = await api.functional.discussionBoard.contentPolicies.patch(connection, {
    body: {},
  });
  typia.assert(res);
  TestValidator.predicate("should include all created policies")(
    res.data.length >= POLICIES.length
  );

  // 3. Search by substring in code ('HATE')
  res = await api.functional.discussionBoard.contentPolicies.patch(connection, {
    body: { code: "HATE" },
  });
  typia.assert(res);
  TestValidator.predicate("Should return only matching policy for code substring 'HATE'")(
    res.data.every(p => p.code.includes("HATE"))
  );

  // 4. Filter by is_active=true (active policies)
  res = await api.functional.discussionBoard.contentPolicies.patch(connection, { body: { is_active: true } });
  typia.assert(res);
  TestValidator.predicate("All should be active")(
    res.data.every(p => p.is_active === true)
  );

  // 5. Filter by is_active=false (inactive policies)
  res = await api.functional.discussionBoard.contentPolicies.patch(connection, { body: { is_active: false } });
  typia.assert(res);
  TestValidator.predicate("All should be inactive")(
    res.data.every(p => p.is_active === false)
  );

  // 6. Filter expired (effective_to in the past)
  const now = new Date();
  res = await api.functional.discussionBoard.contentPolicies.patch(connection, {
    body: { effective_to: now.toISOString() as string & tags.Format<"date-time"> },
  });
  typia.assert(res);
  TestValidator.predicate("Returned policies should have effective_to in the past or null")(
    res.data.every(p => !p.effective_to || new Date(p.effective_to) <= now)
  );

  // 7. Pagination: limit 2 per page, loop pages
  let page = 1;
  let allResults: typeof res.data = [];
  while (true) {
    const paged = await api.functional.discussionBoard.contentPolicies.patch(connection, { body: { page, } });
    typia.assert(paged);
    allResults = allResults.concat(paged.data);
    if (paged.data.length < paged.pagination.limit) break;
    page++;
    if (page > 100) break;
  }
  TestValidator.predicate("Pagination collects all created policies")(
    allResults.length >= POLICIES.length
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
