/**
 * Validate successful retrieval of a single content policy by ID (active and archived).
 *
 * This test ensures that when a content policy is created (active or inactive), it can be
 * reliably fetched by its unique ID and that all important fields exactly match those initial values.
 * This covers both active (currently valid) and archived (inactive/expired) policies.
 *
 * Steps:
 * 1. Create an active content policy (is_active: true, effective_to: null)
 * 2. Retrieve the content policy by ID and validate all fields
 * 3. Create an inactive (archived) policy (is_active: false, effective_to: set to a past date)
 * 4. Retrieve the archived policy by ID and validate all fields
 */
export async function test_api_discussionBoard_contentPolicies_getById_success(
  connection: api.IConnection,
) {
  // 1. Create an active content policy
  const activeCreate = {
    code: `ACTIVE_${RandomGenerator.alphaNumeric(8)}`,
    title: "Active Policy Title",
    description: "Active Policy Description.",
    effective_from: new Date().toISOString(),
    effective_to: null,
    is_active: true,
  } satisfies DiscussionBoardContentPolicies.ICreate;
  const activePolicy = await api.functional.discussionBoard.contentPolicies.post(connection, { body: activeCreate });
  typia.assert(activePolicy);

  // 2. Retrieve the active policy by ID
  const fetchedActive = await api.functional.discussionBoard.contentPolicies.getById(connection, { id: activePolicy.id });
  typia.assert(fetchedActive);

  // Validate all main fields match
  TestValidator.equals("id matches")(fetchedActive.id)(activePolicy.id);
  TestValidator.equals("code matches")(fetchedActive.code)(activeCreate.code);
  TestValidator.equals("title matches")(fetchedActive.title)(activeCreate.title);
  TestValidator.equals("description matches")(fetchedActive.description)(activeCreate.description);
  TestValidator.equals("effective_from matches")(fetchedActive.effective_from)(activeCreate.effective_from);
  TestValidator.equals("effective_to matches")(fetchedActive.effective_to)(null);
  TestValidator.equals("is_active matches")(fetchedActive.is_active)(true);
  TestValidator.predicate("created_at present")(typeof fetchedActive.created_at === "string");
  TestValidator.predicate("updated_at present")(typeof fetchedActive.updated_at === "string");

  // 3. Create an inactive (archived) content policy
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  const archivedCreate = {
    code: `ARCHIVED_${RandomGenerator.alphaNumeric(8)}`,
    title: "Archived Policy Title",
    description: "Archived Policy Description.",
    effective_from: yesterday,
    effective_to: yesterday,
    is_active: false,
  } satisfies DiscussionBoardContentPolicies.ICreate;
  const archivedPolicy = await api.functional.discussionBoard.contentPolicies.post(connection, { body: archivedCreate });
  typia.assert(archivedPolicy);

  // 4. Retrieve the archived policy by ID and validate
  const fetchedArchived = await api.functional.discussionBoard.contentPolicies.getById(connection, { id: archivedPolicy.id });
  typia.assert(fetchedArchived);

  TestValidator.equals("id matches")(fetchedArchived.id)(archivedPolicy.id);
  TestValidator.equals("code matches")(fetchedArchived.code)(archivedCreate.code);
  TestValidator.equals("title matches")(fetchedArchived.title)(archivedCreate.title);
  TestValidator.equals("description matches")(fetchedArchived.description)(archivedCreate.description);
  TestValidator.equals("effective_from matches")(fetchedArchived.effective_from)(archivedCreate.effective_from);
  TestValidator.equals("effective_to matches")(fetchedArchived.effective_to)(yesterday);
  TestValidator.equals("is_active matches")(fetchedArchived.is_active)(false);
  TestValidator.predicate("created_at present")(typeof fetchedArchived.created_at === "string");
  TestValidator.predicate("updated_at present")(typeof fetchedArchived.updated_at === "string");
}

