 *
 * Steps:
 * 1. Prepare a valid policy creation request as baseline (not sent, just for reference)
 * 2. Prepare a request with effective_from set to a date later than effective_to (i.e. inversion: expiration before effect)
 * 3. Attempt to create the policy with this invalid time range
 * 4. Verify that the API rejects the request and throws a validation error
 * 5. Confirm that no policy record is created and the response conveys the nature of the error (business logic enforcement)
 */
export async function test_api_discussionBoard_test_create_content_policy_with_invalid_time_range(
  connection: api.IConnection,
) {
